INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$eaded344$SATQ$, $SATQ$182112b4-ebcd-4ac5-ab27-9cec07d22c6a$SATQ$::uuid, $SATQ$3b0b4d14-3dfb-45c3-821b-140f16592557$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>The painter Frida Kahlo is one of the most influential artists of the twentieth century.</li>
<li>She was born in Coyoac&aacute;n, Mexico, in 1907.</li>
<li>She is best known for her vivid and richly symbolic self-portraits.</li>
<li><em>The Two Fridas</em> (1939) features two versions of Kahlo sitting together.</li>
<li>One version wears a European-style dress and the other a traditional Tehuana dress.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to introduce Kahlo to an audience unfamiliar with the artist. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"b512034d-5002-4e8e-83d5-11a461295eaa","content":"<p>Known for being vivid and richly symbolic, Frida Kahlo&rsquo;s self-portraits include <em>The Two Fridas </em>(1939).</p>"},{"id":"e942312c-88b8-404e-a8d1-dd0b05957dfc","content":"<p>The 1939 painting <em>The Two Fridas </em>is one example of a self-portrait by Frida Kahlo.</p>"},{"id":"12ee10b9-0efd-47ce-a99d-4762894c0727","content":"<p>One painting by Frida Kahlo features two versions of herself, with one version wearing a European-style dress and the other a traditional Tehuana dress.</p>"},{"id":"3d540a4f-b771-4287-b3e4-26560714f653","content":"<p>One of the most influential artists of the twentieth century, Mexican painter Frida Kahlo is best known for her self-portraits, which are vivid and richly symbolic.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["3d540a4f-b771-4287-b3e4-26560714f653"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. By identifying Kahlo as an influential artist from Mexico, and by describing the work she&rsquo;s best known for, this choice provides the background information necessary to introduce Kahlo to an unfamiliar audience. </p><p>Choice A is incorrect. This choice doesn&rsquo;t effectively introduce Kahlo. It doesn&rsquo;t include any background information about who Kahlo is or where she&rsquo;s from. It simply identifies one of her paintings. Choice B is incorrect. This choice doesn&rsquo;t effectively introduce Kahlo. It doesn&rsquo;t include any background information about who Kahlo is or where she&rsquo;s from. It simply identifies one of her paintings. Choice C is incorrect. This choice doesn&rsquo;t effectively introduce Kahlo. It doesn&rsquo;t include any background information about who Kahlo is or where she&rsquo;s from. Instead, it describes one of her paintings in detail. </p>$SATQ$, false, 0, $SATQ$OSP-KA-SYN-E001$SATQ$, $SATQ$$SATQ$, $SATQ$1c7b1f79-2c97-4bfb-83af-e86807cc3cf4$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"eaded344","external_id":"182112b4-ebcd-4ac5-ab27-9cec07d22c6a","vaultid":"3b0b4d14-3dfb-45c3-821b-140f16592557","uId":"d4a6742e-5a05-49b8-99ad-baceea97c93f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>The painter Frida Kahlo is one of the most influential artists of the twentieth century.</li>\n<li>She was born in Coyoac&aacute;n, Mexico, in 1907.</li>\n<li>She is best known for her vivid and richly symbolic self-portraits.</li>\n<li><em>The Two Fridas</em> (1939) features two versions of Kahlo sitting together.</li>\n<li>One version wears a European-style dress and the other a traditional Tehuana dress.</li>\n</ul>","stem":"<p>The student wants to introduce Kahlo to an audience unfamiliar with the artist. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"b512034d-5002-4e8e-83d5-11a461295eaa","content":"<p>Known for being vivid and richly symbolic, Frida Kahlo&rsquo;s self-portraits include <em>The Two Fridas </em>(1939).</p>"},{"id":"e942312c-88b8-404e-a8d1-dd0b05957dfc","content":"<p>The 1939 painting <em>The Two Fridas </em>is one example of a self-portrait by Frida Kahlo.</p>"},{"id":"12ee10b9-0efd-47ce-a99d-4762894c0727","content":"<p>One painting by Frida Kahlo features two versions of herself, with one version wearing a European-style dress and the other a traditional Tehuana dress.</p>"},{"id":"3d540a4f-b771-4287-b3e4-26560714f653","content":"<p>One of the most influential artists of the twentieth century, Mexican painter Frida Kahlo is best known for her self-portraits, which are vivid and richly symbolic.</p>"}],"keys":["3d540a4f-b771-4287-b3e4-26560714f653"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. By identifying Kahlo as an influential artist from Mexico, and by describing the work she&rsquo;s best known for, this choice provides the background information necessary to introduce Kahlo to an unfamiliar audience. </p><p>Choice A is incorrect. This choice doesn&rsquo;t effectively introduce Kahlo. It doesn&rsquo;t include any background information about who Kahlo is or where she&rsquo;s from. It simply identifies one of her paintings. Choice B is incorrect. This choice doesn&rsquo;t effectively introduce Kahlo. It doesn&rsquo;t include any background information about who Kahlo is or where she&rsquo;s from. It simply identifies one of her paintings. Choice C is incorrect. This choice doesn&rsquo;t effectively introduce Kahlo. It doesn&rsquo;t include any background information about who Kahlo is or where she&rsquo;s from. Instead, it describes one of her paintings in detail. </p>","parenttemplatename":"OSP-KA-SYN-E001","parenttemplateid":"","templateclusterid":"1c7b1f79-2c97-4bfb-83af-e86807cc3cf4","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959371,"updateDate":1691007959371}$SATQ$::jsonb, 1691007959371, 1691007959371),
    ($SATQ$eae29760$SATQ$, $SATQ$8d61d85b-4737-45cf-883b-03784c97364e$SATQ$::uuid, $SATQ$3e18d252-fac7-4bee-972a-2a5dcf3aa20e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>The calendar used by most of the world (the Gregorian calendar) has 365 days.</li>
<li>Because 365 days can&rsquo;t be divided evenly by 7 (the number of days in a week), calendar dates fall on a different day of the week each year.</li>
<li>The Hanke-Henry permanent calendar, developed as an alternative to the Gregorian calendar, has 364 days.</li>
<li>Because 364 can be divided evenly by 7, calendar dates fall on the same day of the week each year, which supports more predictable scheduling.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to explain an advantage of the Hanke-Henry calendar. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"2b0c0eda-8c81-478c-a20c-67eba6fdfbab","content":"<p>The Gregorian calendar has 365 days, which is one day longer than the Hanke-Henry permanent calendar.</p>"},{"id":"45877ee0-0e23-40d1-bf0c-425d4c221279","content":"<p>Adopting the Hanke-Henry permanent calendar would help solve a problem with the Gregorian calendar.</p>"},{"id":"104b2d64-c06e-43b2-bacc-901a6525d4f4","content":"<p>Designed so calendar dates would occur on the same day of the week each year, the Hanke-Henry calendar supports more predictable scheduling than does the Gregorian calendar.</p>"},{"id":"dbd36cdc-f336-4f8c-a35c-f749fe622ecb","content":"<p>The Hanke-Henry permanent calendar was developed as an alternative to the Gregorian calendar, which is currently the most-used calendar in the world.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["104b2d64-c06e-43b2-bacc-901a6525d4f4"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence explains an advantage of the Hanke-Henry calendar, noting that it supports more predictable scheduling than does the Gregorian calendar and describing how it does so (by having calendar dates occur on the same day each year). </p><p>Choice A is incorrect. The sentence compares the number of days in the Gregorian and Hanke-Henry calendars; it doesn&rsquo;t explain an advantage of the Hanke-Henry calendar. Choice B is incorrect. While the sentence refers to a possible reason to adopt the Hanke-Henry calendar&mdash;that doing so would help solve a problem with the Gregorian calendar&mdash;it doesn&rsquo;t identify the problem or the solution and thus doesn&rsquo;t explain the advantage of the Hanke-Henry calendar. Choice D is incorrect. The sentence describes the origins of the Hanke-Henry calendar; it doesn&rsquo;t explain an advantage of it. </p>$SATQ$, false, 0, $SATQ$OSP-742-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$d40f711a-323c-42d6-85f4-76f565602bfa$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"eae29760","external_id":"8d61d85b-4737-45cf-883b-03784c97364e","vaultid":"3e18d252-fac7-4bee-972a-2a5dcf3aa20e","uId":"f58621c9-74da-4bcc-9ded-22cf2a2d1aba","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>The calendar used by most of the world (the Gregorian calendar) has 365 days.</li>\n<li>Because 365 days can&rsquo;t be divided evenly by 7 (the number of days in a week), calendar dates fall on a different day of the week each year.</li>\n<li>The Hanke-Henry permanent calendar, developed as an alternative to the Gregorian calendar, has 364 days.</li>\n<li>Because 364 can be divided evenly by 7, calendar dates fall on the same day of the week each year, which supports more predictable scheduling.</li>\n</ul>","stem":"<p>The student wants to explain an advantage of the Hanke-Henry calendar. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"2b0c0eda-8c81-478c-a20c-67eba6fdfbab","content":"<p>The Gregorian calendar has 365 days, which is one day longer than the Hanke-Henry permanent calendar.</p>"},{"id":"45877ee0-0e23-40d1-bf0c-425d4c221279","content":"<p>Adopting the Hanke-Henry permanent calendar would help solve a problem with the Gregorian calendar.</p>"},{"id":"104b2d64-c06e-43b2-bacc-901a6525d4f4","content":"<p>Designed so calendar dates would occur on the same day of the week each year, the Hanke-Henry calendar supports more predictable scheduling than does the Gregorian calendar.</p>"},{"id":"dbd36cdc-f336-4f8c-a35c-f749fe622ecb","content":"<p>The Hanke-Henry permanent calendar was developed as an alternative to the Gregorian calendar, which is currently the most-used calendar in the world.</p>"}],"keys":["104b2d64-c06e-43b2-bacc-901a6525d4f4"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence explains an advantage of the Hanke-Henry calendar, noting that it supports more predictable scheduling than does the Gregorian calendar and describing how it does so (by having calendar dates occur on the same day each year). </p><p>Choice A is incorrect. The sentence compares the number of days in the Gregorian and Hanke-Henry calendars; it doesn&rsquo;t explain an advantage of the Hanke-Henry calendar. Choice B is incorrect. While the sentence refers to a possible reason to adopt the Hanke-Henry calendar&mdash;that doing so would help solve a problem with the Gregorian calendar&mdash;it doesn&rsquo;t identify the problem or the solution and thus doesn&rsquo;t explain the advantage of the Hanke-Henry calendar. Choice D is incorrect. The sentence describes the origins of the Hanke-Henry calendar; it doesn&rsquo;t explain an advantage of it. </p>","parenttemplatename":"OSP-742-SYN","parenttemplateid":"","templateclusterid":"d40f711a-323c-42d6-85f4-76f565602bfa","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959350,"updateDate":1691007959350}$SATQ$::jsonb, 1691007959350, 1691007959350),
    ($SATQ$ec03f090$SATQ$, $SATQ$7dca01cd-5a38-4868-b396-5f2e3975d2e7$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>A sestina is a thirty-nine-line poetic form.</li>
<li>Each line of the poem ends with one of six end words, which alternate according to a set pattern.</li>
<li>&ldquo;Forage Sestina&rdquo; is a sestina by Marilyn Hacker.</li>
<li>Its end words are <em>words</em>, <em>structure</em>, <em>wire</em>, <em>beam</em>, <em>wall</em>, and <em>room</em>.</li>
<li>&ldquo;Towards Autumn&rdquo; is a sestina by Marilyn Hacker.</li>
<li>Its end words are <em>daughter</em>, <em>friend</em>, <em>bread</em>, <em>mother</em>, <em>lover</em>, and <em>myself</em>.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to use one of the poems to illustrate the sestina form. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"32ca9ec4-9f12-48b9-a828-b2cddcdba49a","content":"<p>Hacker employs the sestina, a poetic form with thirty-nine lines and six end words, in both &ldquo;Forage Sestina&rdquo; and &ldquo;Towards Autumn.&rdquo;</p>"},{"id":"9565bff4-388e-48f6-b7f3-4a211ce323d7","content":"<p>As a sestina, &ldquo;Towards Autumn&rdquo; contains thirty-nine lines and six end words&mdash;in this case, <em>daughter</em>, <em>friend</em>, <em>bread</em>, <em>mother</em>, <em>lover</em>, and <em>myself</em>&mdash;that alternate in a set pattern.</p>"},{"id":"6d9dda89-7240-432e-9756-e440a8c0d0d1","content":"<p>The thirty-nine-line sestina form uses the words <em>daughter</em>, <em>friend</em>, <em>bread</em>, <em>mother</em>, <em>lover</em>, and <em>myself</em>, which are found in the poem &ldquo;Forage Sestina.&rdquo;</p>"},{"id":"92cb9d1f-1c68-4c56-92e6-a89e57273a85","content":"<p>Hacker has used the sestina form multiple times, as in &ldquo;Towards Autumn,&rdquo; which contains these six words: <em>words</em>, <em>structure</em>, <em>wire</em>, <em>beam</em>, <em>wall</em>, and <em>room</em>.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["9565bff4-388e-48f6-b7f3-4a211ce323d7"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The sentence uses the poem "Towards Autumn" to illustrate the form of a sestina, explaining that a sestina&rsquo;s thirty-nine lines all end in one of six alternating words and showcasing that poem&rsquo;s specific end words.</p><p>Choice A is incorrect. The sentence identifies both of Hacker&rsquo;s poems as sestinas; it doesn&rsquo;t use one of the poems to illustrate the form of a sestina. Choice C is incorrect. While the sentence appears to use the poem "Forage Sestina" to illustrate a feature of the sestina form, it misrepresents the information in the notes. According to the notes, "Forage Sestina" doesn&rsquo;t use these six end words; it uses six other words instead. Choice D is incorrect. While the sentence uses the poem "Towards Autumn" as an example of one of Hacker&rsquo;s sestinas, it misrepresents the information in the notes. According to the notes, "Towards Autumn" doesn&rsquo;t use these six end words; it uses six other words instead.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"ec03f090","external_id":"7dca01cd-5a38-4868-b396-5f2e3975d2e7","vaultid":null,"uId":"d0a0ae54-86f4-42d8-8a7a-34da1f4bac04","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>A sestina is a thirty-nine-line poetic form.</li>\n<li>Each line of the poem ends with one of six end words, which alternate according to a set pattern.</li>\n<li>&ldquo;Forage Sestina&rdquo; is a sestina by Marilyn Hacker.</li>\n<li>Its end words are <em>words</em>, <em>structure</em>, <em>wire</em>, <em>beam</em>, <em>wall</em>, and <em>room</em>.</li>\n<li>&ldquo;Towards Autumn&rdquo; is a sestina by Marilyn Hacker.</li>\n<li>Its end words are <em>daughter</em>, <em>friend</em>, <em>bread</em>, <em>mother</em>, <em>lover</em>, and <em>myself</em>.</li>\n</ul>","stem":"<p>The student wants to use one of the poems to illustrate the sestina form. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"32ca9ec4-9f12-48b9-a828-b2cddcdba49a","content":"<p>Hacker employs the sestina, a poetic form with thirty-nine lines and six end words, in both &ldquo;Forage Sestina&rdquo; and &ldquo;Towards Autumn.&rdquo;</p>"},{"id":"9565bff4-388e-48f6-b7f3-4a211ce323d7","content":"<p>As a sestina, &ldquo;Towards Autumn&rdquo; contains thirty-nine lines and six end words&mdash;in this case, <em>daughter</em>, <em>friend</em>, <em>bread</em>, <em>mother</em>, <em>lover</em>, and <em>myself</em>&mdash;that alternate in a set pattern.</p>"},{"id":"6d9dda89-7240-432e-9756-e440a8c0d0d1","content":"<p>The thirty-nine-line sestina form uses the words <em>daughter</em>, <em>friend</em>, <em>bread</em>, <em>mother</em>, <em>lover</em>, and <em>myself</em>, which are found in the poem &ldquo;Forage Sestina.&rdquo;</p>"},{"id":"92cb9d1f-1c68-4c56-92e6-a89e57273a85","content":"<p>Hacker has used the sestina form multiple times, as in &ldquo;Towards Autumn,&rdquo; which contains these six words: <em>words</em>, <em>structure</em>, <em>wire</em>, <em>beam</em>, <em>wall</em>, and <em>room</em>.</p>"}],"keys":["9565bff4-388e-48f6-b7f3-4a211ce323d7"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The sentence uses the poem \"Towards Autumn\" to illustrate the form of a sestina, explaining that a sestina&rsquo;s thirty-nine lines all end in one of six alternating words and showcasing that poem&rsquo;s specific end words.</p><p>Choice A is incorrect. The sentence identifies both of Hacker&rsquo;s poems as sestinas; it doesn&rsquo;t use one of the poems to illustrate the form of a sestina. Choice C is incorrect. While the sentence appears to use the poem \"Forage Sestina\" to illustrate a feature of the sestina form, it misrepresents the information in the notes. According to the notes, \"Forage Sestina\" doesn&rsquo;t use these six end words; it uses six other words instead. Choice D is incorrect. While the sentence uses the poem \"Towards Autumn\" as an example of one of Hacker&rsquo;s sestinas, it misrepresents the information in the notes. According to the notes, \"Towards Autumn\" doesn&rsquo;t use these six end words; it uses six other words instead.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323035,"updateDate":1730147323035}$SATQ$::jsonb, 1730147323035, 1730147323035),
    ($SATQ$ec3d7605$SATQ$, $SATQ$4042856b-e301-43f6-8cb7-495dda0e51c4$SATQ$::uuid, $SATQ$aba64c1d-db1a-4c7a-9faa-848cfd67122d$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Award-winning travel writer Linda Watanabe McFerrin considers the background research she conducts on destinations featured in her travel books to be its own reward. <span aria-hidden="true">______</span><span class="sr-only">blank</span> McFerrin admits to finding the research phase of her work just as fascinating and engaging as exploring a location in person.  </p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"6dc75e59-d427-47f1-b757-1c72fa9cdbbe","content":"<p>By contrast,</p>"},{"id":"08075a85-c141-4673-a210-21e913154e82","content":"<p>Likewise,</p>"},{"id":"492e6988-dcf5-42a9-a085-db53103f4fbd","content":"<p>Besides,</p>"},{"id":"6f451386-a5b1-4b9a-a9cd-2379fe4ede48","content":"<p>In fact,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["6f451386-a5b1-4b9a-a9cd-2379fe4ede48"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. &ldquo;In fact&rdquo; logically signals that the information in this sentence&mdash;that McFerrin finds the research phase of her work to be just as fascinating as travel&mdash;emphasizes and elaborates on the previous sentence&rsquo;s point that McFerrin regards background research as a rewarding activity. </p><p>Choice A is incorrect because &ldquo;by contrast&rdquo; illogically signals that the information in this sentence contrasts with the previous sentence&rsquo;s point about McFerrin&rsquo;s attitude toward background research. Instead, it emphasizes and elaborates on that point. Choice B is incorrect because &ldquo;likewise&rdquo; illogically signals that this sentence merely adds a second, similar point to the previous sentence&rsquo;s point about McFerrin&rsquo;s attitude toward background research. Instead, it emphasizes and elaborates on that point. Choice C is incorrect because &ldquo;besides&rdquo; illogically signals that this sentence provides a separate point in addition to, or apart from, the previous sentence&rsquo;s point about McFerrin&rsquo;s attitude toward background research. Instead, it emphasizes and elaborates on that point.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-231-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$c6de56aa-bdb7-49e9-ac4f-5b199b62fee6$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"ec3d7605","external_id":"4042856b-e301-43f6-8cb7-495dda0e51c4","vaultid":"aba64c1d-db1a-4c7a-9faa-848cfd67122d","uId":"10724406-5c32-46a4-9f76-eb4bd7fdd49a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Award-winning travel writer Linda Watanabe McFerrin considers the background research she conducts on destinations featured in her travel books to be its own reward. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> McFerrin admits to finding the research phase of her work just as fascinating and engaging as exploring a location in person.  </p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"6dc75e59-d427-47f1-b757-1c72fa9cdbbe","content":"<p>By contrast,</p>"},{"id":"08075a85-c141-4673-a210-21e913154e82","content":"<p>Likewise,</p>"},{"id":"492e6988-dcf5-42a9-a085-db53103f4fbd","content":"<p>Besides,</p>"},{"id":"6f451386-a5b1-4b9a-a9cd-2379fe4ede48","content":"<p>In fact,</p>"}],"keys":["6f451386-a5b1-4b9a-a9cd-2379fe4ede48"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. &ldquo;In fact&rdquo; logically signals that the information in this sentence&mdash;that McFerrin finds the research phase of her work to be just as fascinating as travel&mdash;emphasizes and elaborates on the previous sentence&rsquo;s point that McFerrin regards background research as a rewarding activity. </p><p>Choice A is incorrect because &ldquo;by contrast&rdquo; illogically signals that the information in this sentence contrasts with the previous sentence&rsquo;s point about McFerrin&rsquo;s attitude toward background research. Instead, it emphasizes and elaborates on that point. Choice B is incorrect because &ldquo;likewise&rdquo; illogically signals that this sentence merely adds a second, similar point to the previous sentence&rsquo;s point about McFerrin&rsquo;s attitude toward background research. Instead, it emphasizes and elaborates on that point. Choice C is incorrect because &ldquo;besides&rdquo; illogically signals that this sentence provides a separate point in addition to, or apart from, the previous sentence&rsquo;s point about McFerrin&rsquo;s attitude toward background research. Instead, it emphasizes and elaborates on that point.&nbsp;</p>","parenttemplatename":"OSP-231-TRA","parenttemplateid":"","templateclusterid":"c6de56aa-bdb7-49e9-ac4f-5b199b62fee6","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959333,"updateDate":1691007959333}$SATQ$::jsonb, 1691007959333, 1691007959333),
    ($SATQ$ecb31049$SATQ$, $SATQ$305de7e7-1899-4dd5-a658-e651cf87c5c3$SATQ$::uuid, $SATQ$c5845bd5-ee28-4c4a-b572-d41f6ce25969$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>The Sun and other stars are powered by nuclear fusion reactions, in which two atoms collide to form a single heavier atom, releasing energy. Scientists have long believed that fusion has the potential to meet humanity&rsquo;s clean energy needs. <span aria-hidden="true">______</span><span class="sr-only">blank</span> prior to December 2022, no fusion reaction in a laboratory setting had ever generated a net energy gain.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"114c4ada-ecbb-43e1-8d85-db6df7e40638","content":"<p>For this reason,</p>"},{"id":"495c7930-2bdd-4af8-ab68-6da994cfcf74","content":"<p>Moreover,</p>"},{"id":"692b3f74-7f80-4505-a3d4-2bab8c8300ca","content":"<p>Specifically,</p>"},{"id":"56b1e2f0-6e13-4612-9645-165780a19d07","content":"<p>That said,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["56b1e2f0-6e13-4612-9645-165780a19d07"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. Scientists believe in fusion&rsquo;s potential as an energy source, but have struggled to actually make it work&mdash;in other words, there is a contradiction between scientists&rsquo; beliefs and their reality. &ldquo;That said&rdquo; is a disagreement transition that works perfectly in this context. </p><p>Choice A is incorrect. This choice uses a cause-and-effect transition, which doesn&rsquo;t make sense here. Scientists not being able to generate extra energy from lab fusion reactions isn&rsquo;t an effect of them believing in fusion&rsquo;s potential. Choice B is incorrect. This transition indicates the addition of another supporting point. But this sentence is not adding a supporting point to the previous sentence&mdash;scientists not being able to successfully generate energy from fusion isn&rsquo;t another point in favor of fusion meeting humanity&rsquo;s clean energy needs. Choice C is incorrect. This choice uses a transition that introduces or elaborates on a particular example. But this sentence doesn&rsquo;t give an example of scientists&rsquo; belief in fusion&rsquo;s potential to meet humanity&rsquo;s clean energy needs&mdash;in fact, it contrasts that optimistic belief with the reality of past failures to successfully employ fusion for energy production. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TRA-H009$SATQ$, $SATQ$$SATQ$, $SATQ$8eb39a84-7a8c-4ebf-a484-83537ee5f71b$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"ecb31049","external_id":"305de7e7-1899-4dd5-a658-e651cf87c5c3","vaultid":"c5845bd5-ee28-4c4a-b572-d41f6ce25969","uId":"ef4919d7-2856-4186-97fe-1dfe1ce18f8f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>The Sun and other stars are powered by nuclear fusion reactions, in which two atoms collide to form a single heavier atom, releasing energy. Scientists have long believed that fusion has the potential to meet humanity&rsquo;s clean energy needs. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> prior to December 2022, no fusion reaction in a laboratory setting had ever generated a net energy gain.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"114c4ada-ecbb-43e1-8d85-db6df7e40638","content":"<p>For this reason,</p>"},{"id":"495c7930-2bdd-4af8-ab68-6da994cfcf74","content":"<p>Moreover,</p>"},{"id":"692b3f74-7f80-4505-a3d4-2bab8c8300ca","content":"<p>Specifically,</p>"},{"id":"56b1e2f0-6e13-4612-9645-165780a19d07","content":"<p>That said,</p>"}],"keys":["56b1e2f0-6e13-4612-9645-165780a19d07"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. Scientists believe in fusion&rsquo;s potential as an energy source, but have struggled to actually make it work&mdash;in other words, there is a contradiction between scientists&rsquo; beliefs and their reality. &ldquo;That said&rdquo; is a disagreement transition that works perfectly in this context. </p><p>Choice A is incorrect. This choice uses a cause-and-effect transition, which doesn&rsquo;t make sense here. Scientists not being able to generate extra energy from lab fusion reactions isn&rsquo;t an effect of them believing in fusion&rsquo;s potential. Choice B is incorrect. This transition indicates the addition of another supporting point. But this sentence is not adding a supporting point to the previous sentence&mdash;scientists not being able to successfully generate energy from fusion isn&rsquo;t another point in favor of fusion meeting humanity&rsquo;s clean energy needs. Choice C is incorrect. This choice uses a transition that introduces or elaborates on a particular example. But this sentence doesn&rsquo;t give an example of scientists&rsquo; belief in fusion&rsquo;s potential to meet humanity&rsquo;s clean energy needs&mdash;in fact, it contrasts that optimistic belief with the reality of past failures to successfully employ fusion for energy production. </p>","parenttemplatename":"OSP-KA-TRA-H009","parenttemplateid":"","templateclusterid":"8eb39a84-7a8c-4ebf-a484-83537ee5f71b","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959373,"updateDate":1691007959373}$SATQ$::jsonb, 1691007959373, 1691007959373),
    ($SATQ$ed80971c$SATQ$, $SATQ$295d509c-ccd0-4431-a2f8-9a68b59825c6$SATQ$::uuid, $SATQ$bb2b916f-5740-4ed0-a973-14a1062b8aa4$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>The Pueblo of Zuni is located about 150 miles west of Albuquerque, New Mexico.</li>
<li>It is the traditional home of the A:shiwi (Zuni) people.</li>
<li>The A:shiwi A:wan Museum and Heritage Center was established by tribal members in 1992.</li>
<li>Its mission is stated on its website: &ldquo;As a tribal museum and heritage center for the Zuni people and by the Zuni people we work to provide learning experiences that emphasize A:shiwi ways of knowing, as well as exploring modern concepts of knowledge and the transfer of knowledge.&rdquo;</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize how long the museum has existed. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"74ea3f17-5c71-4391-b465-93532836b905","content":"<p>The Pueblo of Zuni is home to the A:shiwi A:wan Museum and Heritage Center, which was founded by tribal members.</p>"},{"id":"dc391df0-5355-4a9f-b7dd-e38edb648bcf","content":"<p>The A:shiwi A:wan Museum and Heritage Center has served the Pueblo of Zuni since 1992.</p>"},{"id":"4994c36d-e2de-48b3-955b-c8f22d7f4909","content":"<p>According to its website, the A:shiwi A:wan Museum and Heritage Center (founded in the 1990s) works to &ldquo;emphasize A:shiwi ways of knowing.&rdquo;</p>"},{"id":"94120631-7b11-4473-b211-8c5d6dda218d","content":"<p>Knowledge has been one of the central themes of the A:shiwi A:wan Museum and Heritage Center from its founding.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["dc391df0-5355-4a9f-b7dd-e38edb648bcf"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. This choice effectively uses information from the notes to emphasize how long the museum has existed. It says that the museum has existed since 1992. </p><p>Choice A is incorrect. This choice doesn&rsquo;t emphasize how long the museum has existed. It doesn&rsquo;t say when the museum was founded.&nbsp;Choice C is incorrect. This choice doesn&rsquo;t emphasize how long the museum has existed. It doesn&rsquo;t say the exact date of the museum&rsquo;s founding. Rather, it emphasizes the museum&rsquo;s mission.&nbsp;Choice D is incorrect. This choice doesn&rsquo;t emphasize how long the museum has existed. It doesn&rsquo;t say when the museum was founded.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-712-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$0540c635-884c-4add-a003-2e822604e560$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"ed80971c","external_id":"295d509c-ccd0-4431-a2f8-9a68b59825c6","vaultid":"bb2b916f-5740-4ed0-a973-14a1062b8aa4","uId":"cb1595f1-c7ed-4688-a162-211a5ba234c5","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>The Pueblo of Zuni is located about 150 miles west of Albuquerque, New Mexico.</li>\n<li>It is the traditional home of the A:shiwi (Zuni) people.</li>\n<li>The A:shiwi A:wan Museum and Heritage Center was established by tribal members in 1992.</li>\n<li>Its mission is stated on its website: &ldquo;As a tribal museum and heritage center for the Zuni people and by the Zuni people we work to provide learning experiences that emphasize A:shiwi ways of knowing, as well as exploring modern concepts of knowledge and the transfer of knowledge.&rdquo;</li>\n</ul>","stem":"<p>The student wants to emphasize how long the museum has existed. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"74ea3f17-5c71-4391-b465-93532836b905","content":"<p>The Pueblo of Zuni is home to the A:shiwi A:wan Museum and Heritage Center, which was founded by tribal members.</p>"},{"id":"dc391df0-5355-4a9f-b7dd-e38edb648bcf","content":"<p>The A:shiwi A:wan Museum and Heritage Center has served the Pueblo of Zuni since 1992.</p>"},{"id":"4994c36d-e2de-48b3-955b-c8f22d7f4909","content":"<p>According to its website, the A:shiwi A:wan Museum and Heritage Center (founded in the 1990s) works to &ldquo;emphasize A:shiwi ways of knowing.&rdquo;</p>"},{"id":"94120631-7b11-4473-b211-8c5d6dda218d","content":"<p>Knowledge has been one of the central themes of the A:shiwi A:wan Museum and Heritage Center from its founding.</p>"}],"keys":["dc391df0-5355-4a9f-b7dd-e38edb648bcf"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. This choice effectively uses information from the notes to emphasize how long the museum has existed. It says that the museum has existed since 1992. </p><p>Choice A is incorrect. This choice doesn&rsquo;t emphasize how long the museum has existed. It doesn&rsquo;t say when the museum was founded.&nbsp;Choice C is incorrect. This choice doesn&rsquo;t emphasize how long the museum has existed. It doesn&rsquo;t say the exact date of the museum&rsquo;s founding. Rather, it emphasizes the museum&rsquo;s mission.&nbsp;Choice D is incorrect. This choice doesn&rsquo;t emphasize how long the museum has existed. It doesn&rsquo;t say when the museum was founded.&nbsp;</p>","parenttemplatename":"OSP-712-SYN","parenttemplateid":"","templateclusterid":"0540c635-884c-4add-a003-2e822604e560","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959348,"updateDate":1691007959348}$SATQ$::jsonb, 1691007959348, 1691007959348),
    ($SATQ$edf30612$SATQ$, $SATQ$a06f47da-7544-430d-9c92-a51c690bef56$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>In the late twentieth century, scholars directed much discussion toward issues of spatiality. Adherents to quantitative analytical approaches delineated space with the use of GIS spatial technologies; <span aria-hidden="true">______</span><span class="sr-only">blank</span> cultural geographer Doreen Massey defined space as the product of &ldquo;an ever-shifting social geometry of power and signification,&rdquo; focusing instead on socio-political forces.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"2d38dfbc-f3d2-450b-afd5-4f6eed75a614","content":"<p>for example,</p>"},{"id":"012fa8c1-88d8-4c89-825e-8c86816279e2","content":"<p>by contrast,</p>"},{"id":"22725353-ff2e-429c-823a-75c7e0c30b9a","content":"<p>as such,</p>"},{"id":"8b5e1669-bb81-4129-9d51-bb0e14df09b5","content":"<p>likewise,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["012fa8c1-88d8-4c89-825e-8c86816279e2"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. "By contrast" logically signals that the information about how Massey defined space&mdash;by focusing on socio-political forces&mdash;contrasts with the information in the previous clause, which discusses quantitative analytical approaches and spatial technologies.</p><p>Choice A is incorrect because "for example" illogically signals that the information that follows in the sentence exemplifies the quantitative analytical approaches to defining space described previously. Instead, the information about Massey&rsquo;s socio-political focus presents a contrasting approach. Choice C is incorrect because "as such" illogically signals that the information that follows in the sentence is a direct result or logical consequence of the quantitative analytical approaches to defining space described previously. Instead, the information about Massey&rsquo;s socio-political focus presents a contrasting approach. Choice D is incorrect because "likewise" illogically signals that the information that follows in the sentence is similar to the quantitative analytical approaches to defining space described previously. Instead, the information about Massey&rsquo;s socio-political focus presents a contrasting approach.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"edf30612","external_id":"a06f47da-7544-430d-9c92-a51c690bef56","vaultid":null,"uId":"91ad97c7-e8c7-409f-b355-b0e654ccfe44","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>In the late twentieth century, scholars directed much discussion toward issues of spatiality. Adherents to quantitative analytical approaches delineated space with the use of GIS spatial technologies; <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> cultural geographer Doreen Massey defined space as the product of &ldquo;an ever-shifting social geometry of power and signification,&rdquo; focusing instead on socio-political forces.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"2d38dfbc-f3d2-450b-afd5-4f6eed75a614","content":"<p>for example,</p>"},{"id":"012fa8c1-88d8-4c89-825e-8c86816279e2","content":"<p>by contrast,</p>"},{"id":"22725353-ff2e-429c-823a-75c7e0c30b9a","content":"<p>as such,</p>"},{"id":"8b5e1669-bb81-4129-9d51-bb0e14df09b5","content":"<p>likewise,</p>"}],"keys":["012fa8c1-88d8-4c89-825e-8c86816279e2"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. \"By contrast\" logically signals that the information about how Massey defined space&mdash;by focusing on socio-political forces&mdash;contrasts with the information in the previous clause, which discusses quantitative analytical approaches and spatial technologies.</p><p>Choice A is incorrect because \"for example\" illogically signals that the information that follows in the sentence exemplifies the quantitative analytical approaches to defining space described previously. Instead, the information about Massey&rsquo;s socio-political focus presents a contrasting approach. Choice C is incorrect because \"as such\" illogically signals that the information that follows in the sentence is a direct result or logical consequence of the quantitative analytical approaches to defining space described previously. Instead, the information about Massey&rsquo;s socio-political focus presents a contrasting approach. Choice D is incorrect because \"likewise\" illogically signals that the information that follows in the sentence is similar to the quantitative analytical approaches to defining space described previously. Instead, the information about Massey&rsquo;s socio-political focus presents a contrasting approach.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061190,"updateDate":1755117061190}$SATQ$::jsonb, 1755117061190, 1755117061190),
    ($SATQ$eea351c4$SATQ$, $SATQ$5401b4e3-2d70-43a2-b7df-384959606a0f$SATQ$::uuid, $SATQ$67d926cf-c48a-4e3c-bf03-0ac8c8741862$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>&ldquo;Wishcycling&rdquo;&mdash;putting nonrecyclable items into recycling bins under the mistaken belief that those items can be recycled&mdash;ultimately does more harm than good. Nonrecyclable items, such as greasy pizza boxes, can contaminate recyclable materials, rendering entire batches unusable. <span aria-hidden="true">______</span><span class="sr-only">blank</span> nonrecyclable products can damage recycling plants&rsquo; machinery.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"b77035c9-69e0-4246-a6f0-90a80653bd1f","content":"<p>Fittingly,&nbsp;</p>"},{"id":"edc9a4b0-96b0-41fa-8a27-b81155a7c1c8","content":"<p>On the contrary,</p>"},{"id":"e8aeebaf-4800-451e-ae06-e788c3c6f855","content":"<p>Moreover,</p>"},{"id":"0246c8ec-6b84-46a2-b69d-7c6852b0bd3c","content":"<p>Nevertheless,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["e8aeebaf-4800-451e-ae06-e788c3c6f855"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The first sentence tells us that &ldquo;wishcycling&rdquo; is harmful, the previous sentence gives us an example, and this sentence gives us another example. So &ldquo;moreover&rdquo;&mdash;a transition that indicates the addition of another supporting point&mdash;fits perfectly here. </p><p>Choice A is incorrect. This choice uses a transition that means &ldquo;appropriately&rdquo; or &ldquo;suitably,&rdquo; which doesn&rsquo;t make sense in context. This sentence adds another example of how &ldquo;wishcycling&rdquo; is harmful, so we&rsquo;re looking for an addition transition. Choice B is incorrect. This choice uses a disagreement transition. But this sentence actually agrees with the previous sentence. Both provide examples of how &ldquo;wishcycling&rdquo; is harmful. Choice D is incorrect. This choice uses a disagreement transition. But this sentence actually agrees with the previous sentence. Both provide examples of how &ldquo;wishcycling&rdquo; is harmful. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TRA-M004$SATQ$, $SATQ$$SATQ$, $SATQ$187e35fa-f753-4f5d-aad2-7cf3eeea0497$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"eea351c4","external_id":"5401b4e3-2d70-43a2-b7df-384959606a0f","vaultid":"67d926cf-c48a-4e3c-bf03-0ac8c8741862","uId":"f3069d8c-52a6-42e3-bd04-f3eba9d4568d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>&ldquo;Wishcycling&rdquo;&mdash;putting nonrecyclable items into recycling bins under the mistaken belief that those items can be recycled&mdash;ultimately does more harm than good. Nonrecyclable items, such as greasy pizza boxes, can contaminate recyclable materials, rendering entire batches unusable. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> nonrecyclable products can damage recycling plants&rsquo; machinery.&nbsp;</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"b77035c9-69e0-4246-a6f0-90a80653bd1f","content":"<p>Fittingly,&nbsp;</p>"},{"id":"edc9a4b0-96b0-41fa-8a27-b81155a7c1c8","content":"<p>On the contrary,</p>"},{"id":"e8aeebaf-4800-451e-ae06-e788c3c6f855","content":"<p>Moreover,</p>"},{"id":"0246c8ec-6b84-46a2-b69d-7c6852b0bd3c","content":"<p>Nevertheless,</p>"}],"keys":["e8aeebaf-4800-451e-ae06-e788c3c6f855"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The first sentence tells us that &ldquo;wishcycling&rdquo; is harmful, the previous sentence gives us an example, and this sentence gives us another example. So &ldquo;moreover&rdquo;&mdash;a transition that indicates the addition of another supporting point&mdash;fits perfectly here. </p><p>Choice A is incorrect. This choice uses a transition that means &ldquo;appropriately&rdquo; or &ldquo;suitably,&rdquo; which doesn&rsquo;t make sense in context. This sentence adds another example of how &ldquo;wishcycling&rdquo; is harmful, so we&rsquo;re looking for an addition transition. Choice B is incorrect. This choice uses a disagreement transition. But this sentence actually agrees with the previous sentence. Both provide examples of how &ldquo;wishcycling&rdquo; is harmful. Choice D is incorrect. This choice uses a disagreement transition. But this sentence actually agrees with the previous sentence. Both provide examples of how &ldquo;wishcycling&rdquo; is harmful. </p>","parenttemplatename":"OSP-KA-TRA-M004","parenttemplateid":"","templateclusterid":"187e35fa-f753-4f5d-aad2-7cf3eeea0497","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959373,"updateDate":1691007959373}$SATQ$::jsonb, 1691007959373, 1691007959373),
    ($SATQ$efa2be4f$SATQ$, $SATQ$8e115ea7-bbb9-40f5-b9fe-5a8745b61654$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>The meter of a poem is the rhythmic structure or pattern of accents in its lines.</li>
<li>Alliterative meter is structured by a pattern of repeated sounds.</li>
<li>Quantitative meter is structured by a pattern of long and short syllables.</li>
<li>The Old English poem <em>Widsith</em> uses an alliterative meter.</li>
<li>The Sanskrit poem <em>Meghadūta</em> uses a quantitative meter.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize a difference between the meters of the two poems. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"be170e19-1ede-481f-b233-6fda3bfe0cdc","content":"<p>The poem <em>Widsith </em>is written in Old English, but <em>Meghadūta</em> is written in Sanskrit.&nbsp;</p>"},{"id":"fa63ad51-5064-4cd6-b1e0-a6156eef02d6","content":"<p>Alliterative meter is a pattern of repeated sounds, but quantitative meter is a rhythmic structure or pattern of accents.</p>"},{"id":"8d696a40-1d75-4f3f-9882-13567ca83df4","content":"<p>The Sanskrit poem <em>Meghadūta </em>uses a quantitative meter, while the meter of the Old English poem <em>Widsith </em>uses a pattern of long and short syllables.&nbsp;</p>"},{"id":"edaefe26-0abf-41d0-b6eb-9dfaab3b0728","content":"<p>The lines of the poem <em>Meghadūta</em> use a pattern of long and short syllables, whereas <em>Widsith</em>&rsquo;s lines use a pattern of repeated sounds.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["edaefe26-0abf-41d0-b6eb-9dfaab3b0728"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. Noting that <em>Meghadūta</em> uses a pattern of long and short syllables in its lines (quantitative meter) and <em>Widsith</em> uses a pattern of repeated sounds in its lines (alliterative meter), and signaling a contrast with &ldquo;whereas,&rdquo; the sentence emphasizes a difference between the meters of the two poems.</p><p>Choice A is incorrect. The sentence indicates that the two poems were written in different languages; it doesn&rsquo;t emphasize a difference between the meters of the two poems. Choice B is incorrect. The sentence mentions the meters of the two poems but misrepresents information from the notes; the overall definition of a meter (the rhythmic structure or pattern of accents in a poem&rsquo;s lines) applies to both alliterative and quantitative meters, not just quantitative. Choice C is incorrect. While the sentence emphasizes a difference between the meters of the two poems, it misrepresents information from the notes; <em>Widsith</em> uses an alliterative meter, which is structured by a pattern of repeated sounds, not a pattern of long and short syllables.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"efa2be4f","external_id":"8e115ea7-bbb9-40f5-b9fe-5a8745b61654","vaultid":null,"uId":"a1f34c4b-a244-4b9b-a0bc-7479c12830ce","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>The meter of a poem is the rhythmic structure or pattern of accents in its lines.</li>\n<li>Alliterative meter is structured by a pattern of repeated sounds.</li>\n<li>Quantitative meter is structured by a pattern of long and short syllables.</li>\n<li>The Old English poem <em>Widsith</em> uses an alliterative meter.</li>\n<li>The Sanskrit poem <em>Meghadūta</em> uses a quantitative meter.</li>\n</ul>","stem":"<p>The student wants to emphasize a difference between the meters of the two poems. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"be170e19-1ede-481f-b233-6fda3bfe0cdc","content":"<p>The poem <em>Widsith </em>is written in Old English, but <em>Meghadūta</em> is written in Sanskrit.&nbsp;</p>"},{"id":"fa63ad51-5064-4cd6-b1e0-a6156eef02d6","content":"<p>Alliterative meter is a pattern of repeated sounds, but quantitative meter is a rhythmic structure or pattern of accents.</p>"},{"id":"8d696a40-1d75-4f3f-9882-13567ca83df4","content":"<p>The Sanskrit poem <em>Meghadūta </em>uses a quantitative meter, while the meter of the Old English poem <em>Widsith </em>uses a pattern of long and short syllables.&nbsp;</p>"},{"id":"edaefe26-0abf-41d0-b6eb-9dfaab3b0728","content":"<p>The lines of the poem <em>Meghadūta</em> use a pattern of long and short syllables, whereas <em>Widsith</em>&rsquo;s lines use a pattern of repeated sounds.</p>"}],"keys":["edaefe26-0abf-41d0-b6eb-9dfaab3b0728"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. Noting that <em>Meghadūta</em> uses a pattern of long and short syllables in its lines (quantitative meter) and <em>Widsith</em> uses a pattern of repeated sounds in its lines (alliterative meter), and signaling a contrast with &ldquo;whereas,&rdquo; the sentence emphasizes a difference between the meters of the two poems.</p><p>Choice A is incorrect. The sentence indicates that the two poems were written in different languages; it doesn&rsquo;t emphasize a difference between the meters of the two poems. Choice B is incorrect. The sentence mentions the meters of the two poems but misrepresents information from the notes; the overall definition of a meter (the rhythmic structure or pattern of accents in a poem&rsquo;s lines) applies to both alliterative and quantitative meters, not just quantitative. Choice C is incorrect. While the sentence emphasizes a difference between the meters of the two poems, it misrepresents information from the notes; <em>Widsith</em> uses an alliterative meter, which is structured by a pattern of repeated sounds, not a pattern of long and short syllables.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771169,"updateDate":1776362771169}$SATQ$::jsonb, 1776362771169, 1776362771169),
    ($SATQ$efc19153$SATQ$, $SATQ$a0186a2e-4208-4287-b388-b90a267672ef$SATQ$::uuid, $SATQ$6a15ba3e-6846-40e5-b4cd-fb88387b3d80$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Just like states have state flags, some cities have city flags.</li>
<li>Over one hundred US cities have redesigned their flags since 2015.</li>
<li>The city of Pocatello, Idaho, redesigned its flag after it was named the most poorly designed flag in North America.</li>
<li>Pocatello&rsquo;s new flag better represents the city&rsquo;s mountainous geography and civic priorities.</li>
<li>Residents consider the new flag to be a meaningful symbol of civic pride.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to make and support a generalization about the effect of redesigning a city flag. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"c3e44d41-30ab-4734-aac2-9e5ea5e8aa30","content":"<p>Over one hundred US cities have redesigned their flags, including Pocatello, whose flag had been named the most poorly designed flag in North America.</p>"},{"id":"618e8033-6f1f-4d5c-acbf-3c8d02726829","content":"<p>Pocatello is just one of over one hundred US cities that have redesigned their flags.</p>"},{"id":"a776ab22-1071-4d09-8f4f-5f8cd29e23cf","content":"<p>After it was named the most poorly designed flag in North America, the flag of Pocatello was redesigned to better represent the city&rsquo;s geography and civic priorities.</p>"},{"id":"fd603bab-0916-4a3f-ad44-01ff1872d417","content":"<p>Redesigning a poorly designed city flag can create a meaningful symbol of civic pride, as was the case when Pocatello redesigned its original flag to better represent its geography and civic priorities.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["fd603bab-0916-4a3f-ad44-01ff1872d417"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The sentence makes and supports a generalization about the effect of redesigning a city flag, noting that redesigning a city flag can create a meaningful symbol of civic pride, as was the case when the city of Pocatello redesigned its flag. </p><p>Choice A is incorrect because the sentence explains that many US cities have redesigned their flags and provides an example; it doesn&rsquo;t make and support a generalization about the effect of redesigning a city flag. Choice B is incorrect because the sentence provides an example of a city that redesigned its flag; it doesn&rsquo;t make and support a generalization about the effect of redesigning a city flag. Choice C is incorrect because the sentence emphasizes why the flag of Pocatello was redesigned; it doesn&rsquo;t make and support a generalization about the effect of redesigning a city flag. </p>$SATQ$, false, 0, $SATQ$OSP-008-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$c9fc1596-9feb-4db5-a2e7-3a3f2dd78197$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"efc19153","external_id":"a0186a2e-4208-4287-b388-b90a267672ef","vaultid":"6a15ba3e-6846-40e5-b4cd-fb88387b3d80","uId":"f585f934-902d-458f-a5b5-58cc58ccd79a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Just like states have state flags, some cities have city flags.</li>\n<li>Over one hundred US cities have redesigned their flags since 2015.</li>\n<li>The city of Pocatello, Idaho, redesigned its flag after it was named the most poorly designed flag in North America.</li>\n<li>Pocatello&rsquo;s new flag better represents the city&rsquo;s mountainous geography and civic priorities.</li>\n<li>Residents consider the new flag to be a meaningful symbol of civic pride.</li>\n</ul>","stem":"<p>The student wants to make and support a generalization about the effect of redesigning a city flag. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"c3e44d41-30ab-4734-aac2-9e5ea5e8aa30","content":"<p>Over one hundred US cities have redesigned their flags, including Pocatello, whose flag had been named the most poorly designed flag in North America.</p>"},{"id":"618e8033-6f1f-4d5c-acbf-3c8d02726829","content":"<p>Pocatello is just one of over one hundred US cities that have redesigned their flags.</p>"},{"id":"a776ab22-1071-4d09-8f4f-5f8cd29e23cf","content":"<p>After it was named the most poorly designed flag in North America, the flag of Pocatello was redesigned to better represent the city&rsquo;s geography and civic priorities.</p>"},{"id":"fd603bab-0916-4a3f-ad44-01ff1872d417","content":"<p>Redesigning a poorly designed city flag can create a meaningful symbol of civic pride, as was the case when Pocatello redesigned its original flag to better represent its geography and civic priorities.&nbsp;</p>"}],"keys":["fd603bab-0916-4a3f-ad44-01ff1872d417"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The sentence makes and supports a generalization about the effect of redesigning a city flag, noting that redesigning a city flag can create a meaningful symbol of civic pride, as was the case when the city of Pocatello redesigned its flag. </p><p>Choice A is incorrect because the sentence explains that many US cities have redesigned their flags and provides an example; it doesn&rsquo;t make and support a generalization about the effect of redesigning a city flag. Choice B is incorrect because the sentence provides an example of a city that redesigned its flag; it doesn&rsquo;t make and support a generalization about the effect of redesigning a city flag. Choice C is incorrect because the sentence emphasizes why the flag of Pocatello was redesigned; it doesn&rsquo;t make and support a generalization about the effect of redesigning a city flag. </p>","parenttemplatename":"OSP-008-SYN","parenttemplateid":"","templateclusterid":"c9fc1596-9feb-4db5-a2e7-3a3f2dd78197","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959313,"updateDate":1691007959313}$SATQ$::jsonb, 1691007959313, 1691007959313),
    ($SATQ$f07570bb$SATQ$, $SATQ$76757b39-2317-4b33-8831-07a58aa322fc$SATQ$::uuid, $SATQ$f83f4fc3-302f-42cb-b460-87be3e8fc7c2$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>Researchers believe that pieces of hull found off Oregon&rsquo;s coast are from a Spanish cargo ship that was lost in 1697. Stories passed down among the area&rsquo;s Confederated Tribes of Siletz Indians support this belief. <span aria-hidden="true">______</span><span class="sr-only">blank</span> Siletz stories describe how blocks of beeswax, an item the ship had been carrying, began washing ashore after the ship was lost.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"a7368e75-84c9-43b5-b33e-12ae765f7c88","content":"<p>For this reason,</p>"},{"id":"227ba0c7-6371-4dd2-84f7-dbc646470d8f","content":"<p>For example,</p>"},{"id":"1641cc94-ce5c-430e-a410-65ec1cb4dd1c","content":"<p>However,</p>"},{"id":"6a01f830-08c7-4586-ab8d-2463a1386884","content":"<p>Likewise,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["227ba0c7-6371-4dd2-84f7-dbc646470d8f"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. &ldquo;For example&rdquo; logically signals that the Siletz beeswax stories mentioned in this sentence are examples consistent with the previous claim that Siletz stories support the shipwreck theory. </p><p>Choice A is incorrect because &ldquo;for this reason&rdquo; illogically signals that the Siletz stories about the beeswax were caused by the previous claim that Siletz stories support the shipwreck theory. Instead, the beeswax stories are examples consistent with the claim. Choice C is incorrect because &ldquo;however&rdquo; illogically signals that the Siletz stories about the beeswax contrast with the previous claim that Siletz stories support the shipwreck theory. Instead, the beeswax stories are examples consistent with the claim. Choice D is incorrect because &ldquo;likewise&rdquo; illogically signals that the Siletz stories about the beeswax are similar to the previous claim that Siletz stories support the shipwreck theory. Instead, the beeswax stories are examples consistent with the claim. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TRA-E001$SATQ$, $SATQ$$SATQ$, $SATQ$23be16e3-60cc-49b1-af7c-440879761662$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f07570bb","external_id":"76757b39-2317-4b33-8831-07a58aa322fc","vaultid":"f83f4fc3-302f-42cb-b460-87be3e8fc7c2","uId":"1f4f1fa3-bcc1-47e0-859b-8c9e41dc204d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>Researchers believe that pieces of hull found off Oregon&rsquo;s coast are from a Spanish cargo ship that was lost in 1697. Stories passed down among the area&rsquo;s Confederated Tribes of Siletz Indians support this belief. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> Siletz stories describe how blocks of beeswax, an item the ship had been carrying, began washing ashore after the ship was lost.&nbsp;</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"a7368e75-84c9-43b5-b33e-12ae765f7c88","content":"<p>For this reason,</p>"},{"id":"227ba0c7-6371-4dd2-84f7-dbc646470d8f","content":"<p>For example,</p>"},{"id":"1641cc94-ce5c-430e-a410-65ec1cb4dd1c","content":"<p>However,</p>"},{"id":"6a01f830-08c7-4586-ab8d-2463a1386884","content":"<p>Likewise,</p>"}],"keys":["227ba0c7-6371-4dd2-84f7-dbc646470d8f"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. &ldquo;For example&rdquo; logically signals that the Siletz beeswax stories mentioned in this sentence are examples consistent with the previous claim that Siletz stories support the shipwreck theory. </p><p>Choice A is incorrect because &ldquo;for this reason&rdquo; illogically signals that the Siletz stories about the beeswax were caused by the previous claim that Siletz stories support the shipwreck theory. Instead, the beeswax stories are examples consistent with the claim. Choice C is incorrect because &ldquo;however&rdquo; illogically signals that the Siletz stories about the beeswax contrast with the previous claim that Siletz stories support the shipwreck theory. Instead, the beeswax stories are examples consistent with the claim. Choice D is incorrect because &ldquo;likewise&rdquo; illogically signals that the Siletz stories about the beeswax are similar to the previous claim that Siletz stories support the shipwreck theory. Instead, the beeswax stories are examples consistent with the claim. </p>","parenttemplatename":"OSP-KA-TRA-E001","parenttemplateid":"","templateclusterid":"23be16e3-60cc-49b1-af7c-440879761662","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959372,"updateDate":1691007959372}$SATQ$::jsonb, 1691007959372, 1691007959372),
    ($SATQ$f114cbf0$SATQ$, $SATQ$42c9687e-7cf5-4c09-8d7b-488a5a1e1fe1$SATQ$::uuid, $SATQ$02ba7e8f-a752-46d5-a227-701c4592d465$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>A firefly uses specialized muscles to draw oxygen into its lower abdomen through narrow tubes, triggering a chemical reaction whereby the oxygen combines with chemicals in the firefly&rsquo;s abdomen to produce a glow. <span aria-hidden="true">______</span><span class="sr-only">blank</span> when the firefly stops drawing in oxygen, the reaction&mdash;and the glow&mdash;cease.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"5c008ff0-28ab-46b0-a29d-898c8b24ebdf","content":"<p>For instance,</p>"},{"id":"66ae1713-ab73-43b8-89d3-73891fc17028","content":"<p>By contrast,</p>"},{"id":"57ff7297-046d-4f0c-8d25-e473fb9f8ab8","content":"<p>Specifically,</p>"},{"id":"1c933139-6171-42f5-b25f-701229e07dc8","content":"<p>In conclusion,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["66ae1713-ab73-43b8-89d3-73891fc17028"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. &ldquo;By contrast&rdquo; logically signals that the information in this sentence&mdash;that a firefly&rsquo;s glow ceases when it stops drawing in oxygen&mdash;contrasts with the previous sentence&rsquo;s discussion of the processes that cause a firefly to begin to glow. </p><p>Choice A is incorrect because &ldquo;for instance&rdquo; illogically signals that the information in the sentence exemplifies the previous sentence&rsquo;s discussion of how a firefly begins to glow. Instead, it contrasts with the previous sentence&rsquo;s discussion. Choice C is incorrect because &ldquo;specifically&rdquo; illogically signals that the information in the sentence provides specific details elaborating on the previous sentence&rsquo;s discussion of how a firefly begins to glow. Instead, it contrasts with the previous sentence&rsquo;s discussion.&nbsp;Choice D is incorrect because &ldquo;in conclusion&rdquo; illogically signals that the information in the sentence sums up the previous sentence&rsquo;s discussion of how a firefly begins to glow. Instead, it contrasts with the previous sentence&rsquo;s discussion.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-226-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$6777926d-275a-4d7d-99a0-033165ec3e38$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f114cbf0","external_id":"42c9687e-7cf5-4c09-8d7b-488a5a1e1fe1","vaultid":"02ba7e8f-a752-46d5-a227-701c4592d465","uId":"ab831e59-4013-4f0c-a1ef-b3bd454bb2de","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>A firefly uses specialized muscles to draw oxygen into its lower abdomen through narrow tubes, triggering a chemical reaction whereby the oxygen combines with chemicals in the firefly&rsquo;s abdomen to produce a glow. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> when the firefly stops drawing in oxygen, the reaction&mdash;and the glow&mdash;cease.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"5c008ff0-28ab-46b0-a29d-898c8b24ebdf","content":"<p>For instance,</p>"},{"id":"66ae1713-ab73-43b8-89d3-73891fc17028","content":"<p>By contrast,</p>"},{"id":"57ff7297-046d-4f0c-8d25-e473fb9f8ab8","content":"<p>Specifically,</p>"},{"id":"1c933139-6171-42f5-b25f-701229e07dc8","content":"<p>In conclusion,</p>"}],"keys":["66ae1713-ab73-43b8-89d3-73891fc17028"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. &ldquo;By contrast&rdquo; logically signals that the information in this sentence&mdash;that a firefly&rsquo;s glow ceases when it stops drawing in oxygen&mdash;contrasts with the previous sentence&rsquo;s discussion of the processes that cause a firefly to begin to glow. </p><p>Choice A is incorrect because &ldquo;for instance&rdquo; illogically signals that the information in the sentence exemplifies the previous sentence&rsquo;s discussion of how a firefly begins to glow. Instead, it contrasts with the previous sentence&rsquo;s discussion. Choice C is incorrect because &ldquo;specifically&rdquo; illogically signals that the information in the sentence provides specific details elaborating on the previous sentence&rsquo;s discussion of how a firefly begins to glow. Instead, it contrasts with the previous sentence&rsquo;s discussion.&nbsp;Choice D is incorrect because &ldquo;in conclusion&rdquo; illogically signals that the information in the sentence sums up the previous sentence&rsquo;s discussion of how a firefly begins to glow. Instead, it contrasts with the previous sentence&rsquo;s discussion.&nbsp;</p>","parenttemplatename":"OSP-226-TRA","parenttemplateid":"","templateclusterid":"6777926d-275a-4d7d-99a0-033165ec3e38","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959332,"updateDate":1691007959332}$SATQ$::jsonb, 1691007959332, 1691007959332),
    ($SATQ$f1631638$SATQ$, $SATQ$34eafb3e-bcab-4b7b-b488-987611a37efb$SATQ$::uuid, $SATQ$b47b13e0-908c-4d53-bf3a-5a8a70607d1b$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Gaspar Enriquez is an artist.</li>
<li>He specializes in portraits of Mexican Americans.</li>
<li>A portrait is an artistic representation of a person.</li>
<li>Enriquez completed a painting of the sculptor Luis Jimenez in 2003.</li>
<li>He completed a drawing of the writer Rudolfo Anaya in 2016.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize a difference between the two portraits. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"5421c423-a5cd-4072-9876-6e3c98751335","content":"<p>The portraits, or artistic representations, of Luis Jimenez and Rudolfo Anaya were both completed by Enriquez in the early 2000s.</p>"},{"id":"174e9356-96a3-448b-9702-d93831cf2ed3","content":"<p>Enriquez has completed portraits of numerous Mexican Americans, including sculptor Luis Jimenez and writer Rudolfo Anaya.&nbsp;</p>"},{"id":"286e44bb-ab0b-43cf-b453-cc6421ee5459","content":"<p>While both are by Enriquez, the 2003 portrait of Luis Jimenez is a painting, and the 2016 portrait of Rudolfo Anaya is a drawing.&nbsp;</p>"},{"id":"a6342746-154a-4fdb-9328-c6ae73472cca","content":"<p>Luis Jimenez was a Mexican American sculptor, and Rudolfo Anaya was a Mexican American writer.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["286e44bb-ab0b-43cf-b453-cc6421ee5459"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence emphasizes a difference between the portraits, noting that one is a painting and the other is a drawing. </p><p>Choice A is incorrect. The sentence emphasizes a similarity between the two portraits rather than a difference. Choice B is incorrect. The sentence makes a generalization about Enriquez&rsquo;s portraits; it doesn&rsquo;t emphasize a difference between the portraits of Jimenez and Anaya. Choice D is incorrect. While the sentence notes a difference between Jimenez and Anaya, it doesn&rsquo;t emphasize a difference between, or even mention, their portraits. </p>$SATQ$, false, 0, $SATQ$OSP-760-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$8be00e4a-71f2-4fcb-9ce5-c23c1e61abe6$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f1631638","external_id":"34eafb3e-bcab-4b7b-b488-987611a37efb","vaultid":"b47b13e0-908c-4d53-bf3a-5a8a70607d1b","uId":"72c3d9e5-3ab9-43fe-8613-822effe9f0cb","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Gaspar Enriquez is an artist.</li>\n<li>He specializes in portraits of Mexican Americans.</li>\n<li>A portrait is an artistic representation of a person.</li>\n<li>Enriquez completed a painting of the sculptor Luis Jimenez in 2003.</li>\n<li>He completed a drawing of the writer Rudolfo Anaya in 2016.</li>\n</ul>","stem":"<p>The student wants to emphasize a difference between the two portraits. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"5421c423-a5cd-4072-9876-6e3c98751335","content":"<p>The portraits, or artistic representations, of Luis Jimenez and Rudolfo Anaya were both completed by Enriquez in the early 2000s.</p>"},{"id":"174e9356-96a3-448b-9702-d93831cf2ed3","content":"<p>Enriquez has completed portraits of numerous Mexican Americans, including sculptor Luis Jimenez and writer Rudolfo Anaya.&nbsp;</p>"},{"id":"286e44bb-ab0b-43cf-b453-cc6421ee5459","content":"<p>While both are by Enriquez, the 2003 portrait of Luis Jimenez is a painting, and the 2016 portrait of Rudolfo Anaya is a drawing.&nbsp;</p>"},{"id":"a6342746-154a-4fdb-9328-c6ae73472cca","content":"<p>Luis Jimenez was a Mexican American sculptor, and Rudolfo Anaya was a Mexican American writer.</p>"}],"keys":["286e44bb-ab0b-43cf-b453-cc6421ee5459"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence emphasizes a difference between the portraits, noting that one is a painting and the other is a drawing. </p><p>Choice A is incorrect. The sentence emphasizes a similarity between the two portraits rather than a difference. Choice B is incorrect. The sentence makes a generalization about Enriquez&rsquo;s portraits; it doesn&rsquo;t emphasize a difference between the portraits of Jimenez and Anaya. Choice D is incorrect. While the sentence notes a difference between Jimenez and Anaya, it doesn&rsquo;t emphasize a difference between, or even mention, their portraits. </p>","parenttemplatename":"OSP-760-SYN","parenttemplateid":"","templateclusterid":"8be00e4a-71f2-4fcb-9ce5-c23c1e61abe6","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959351,"updateDate":1691007959351}$SATQ$::jsonb, 1691007959351, 1691007959351),
    ($SATQ$f1d8550e$SATQ$, $SATQ$e934e3ce-75e8-4e0c-b825-5e84358e4638$SATQ$::uuid, $SATQ$bf007581-8922-48a9-ab88-5a1c4cccb66e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Jordan Bennett is a Mi&rsquo;Kmaq visual artist.</li>
<li>The Mi&rsquo;Kmaq are a First Nations people in North America.</li>
<li>Bennett&rsquo;s paintings pay homage to traditional Mi&rsquo;Kmaq craftsmanship and have been displayed in over 75 exhibitions.</li>
<li>His 2017 exhibition <em>Wije&rsquo;wi</em> was held at the Grenfell Art Gallery.</li>
<li>His 2018 exhibition <em>Ketu&rsquo;elmita&rsquo;jik </em>was held at the Art Gallery of Nova Scotia.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize the order in which two of Jordan Bennett&rsquo;s exhibitions were held. Which choice most effectively uses relevant information from the notes to accomplish this goal?&nbsp;&nbsp;</p>$SATQ$, $SATQ$[{"id":"7436c112-551f-4ed8-b262-fecb9368f1a8","content":"<p>Jordan Bennett&rsquo;s 2017 exhibition <em>Wije&rsquo;wi </em>was followed a year later by his exhibition <em>Ketu&rsquo;elmita&rsquo;jik. </em></p>"},{"id":"69b325ee-1c52-4c10-9c12-387d3733091d","content":"<p>Jordan Bennett&rsquo;s paintings, some of which appeared in 2017 and 2018 exhibitions, pay homage to traditional Mi&rsquo;Kmaq craftsmanship.&nbsp;</p>"},{"id":"6acbb840-1ca1-4c5a-bdf7-ee7e39f74663","content":"<p>Mi&rsquo;Kmaq visual artist Jordan Bennett has displayed his work in over 75 exhibitions, including <em>Wije&rsquo;wi </em>and <em>Ketu&rsquo;elmita&rsquo;jik.</em></p>"},{"id":"adc99824-fc29-42e2-8d7b-caca91abcb82","content":"<p>Jordan Bennett&rsquo;s 2018 exhibition <em>Ketu&rsquo;elmita&rsquo;jik </em>was held at the Art Gallery of Nova Scotia; another was held at the Grenfell Art Gallery.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["7436c112-551f-4ed8-b262-fecb9368f1a8"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The sentence emphasizes the order in which two of Jordan Bennett&rsquo;s exhibitions were held, indicating that <em>Wije&rsquo;wi</em> took place in 2017 and <em>Ketu&rsquo;elmita&rsquo;jik</em> took place a year later (2018). </p><p>Choice B is incorrect. While the sentence mentions that exhibitions of Jordan Bennett&rsquo;s paintings took place in 2017 and 2018, it doesn&rsquo;t identify the exhibitions or emphasize the order in which they were held. Choice C is incorrect. While the sentence mentions two of Jordan Bennett&rsquo;s exhibitions<em>,</em>&nbsp;it doesn&rsquo;t indicate the order in which they were held. Choice D is incorrect. While the sentence mentions two of Jordan Bennett&rsquo;s exhibitions and specifies when one of them was held, it doesn&rsquo;t state when the exhibition at the Grenfell Art Gallery occurred. Thus, the order in which the two exhibitions were held isn&rsquo;t clearly established in the sentence.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-771-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$bbcf0ebf-d38c-4cc7-aebf-895bd1da77f4$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f1d8550e","external_id":"e934e3ce-75e8-4e0c-b825-5e84358e4638","vaultid":"bf007581-8922-48a9-ab88-5a1c4cccb66e","uId":"3be06684-723e-4cf0-9280-4ddf6ec50a33","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Jordan Bennett is a Mi&rsquo;Kmaq visual artist.</li>\n<li>The Mi&rsquo;Kmaq are a First Nations people in North America.</li>\n<li>Bennett&rsquo;s paintings pay homage to traditional Mi&rsquo;Kmaq craftsmanship and have been displayed in over 75 exhibitions.</li>\n<li>His 2017 exhibition <em>Wije&rsquo;wi</em> was held at the Grenfell Art Gallery.</li>\n<li>His 2018 exhibition <em>Ketu&rsquo;elmita&rsquo;jik </em>was held at the Art Gallery of Nova Scotia.</li>\n</ul>","stem":"<p>The student wants to emphasize the order in which two of Jordan Bennett&rsquo;s exhibitions were held. Which choice most effectively uses relevant information from the notes to accomplish this goal?&nbsp;&nbsp;</p>","answerOptions":[{"id":"7436c112-551f-4ed8-b262-fecb9368f1a8","content":"<p>Jordan Bennett&rsquo;s 2017 exhibition <em>Wije&rsquo;wi </em>was followed a year later by his exhibition <em>Ketu&rsquo;elmita&rsquo;jik. </em></p>"},{"id":"69b325ee-1c52-4c10-9c12-387d3733091d","content":"<p>Jordan Bennett&rsquo;s paintings, some of which appeared in 2017 and 2018 exhibitions, pay homage to traditional Mi&rsquo;Kmaq craftsmanship.&nbsp;</p>"},{"id":"6acbb840-1ca1-4c5a-bdf7-ee7e39f74663","content":"<p>Mi&rsquo;Kmaq visual artist Jordan Bennett has displayed his work in over 75 exhibitions, including <em>Wije&rsquo;wi </em>and <em>Ketu&rsquo;elmita&rsquo;jik.</em></p>"},{"id":"adc99824-fc29-42e2-8d7b-caca91abcb82","content":"<p>Jordan Bennett&rsquo;s 2018 exhibition <em>Ketu&rsquo;elmita&rsquo;jik </em>was held at the Art Gallery of Nova Scotia; another was held at the Grenfell Art Gallery.</p>"}],"keys":["7436c112-551f-4ed8-b262-fecb9368f1a8"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The sentence emphasizes the order in which two of Jordan Bennett&rsquo;s exhibitions were held, indicating that <em>Wije&rsquo;wi</em> took place in 2017 and <em>Ketu&rsquo;elmita&rsquo;jik</em> took place a year later (2018). </p><p>Choice B is incorrect. While the sentence mentions that exhibitions of Jordan Bennett&rsquo;s paintings took place in 2017 and 2018, it doesn&rsquo;t identify the exhibitions or emphasize the order in which they were held. Choice C is incorrect. While the sentence mentions two of Jordan Bennett&rsquo;s exhibitions<em>,</em>&nbsp;it doesn&rsquo;t indicate the order in which they were held. Choice D is incorrect. While the sentence mentions two of Jordan Bennett&rsquo;s exhibitions and specifies when one of them was held, it doesn&rsquo;t state when the exhibition at the Grenfell Art Gallery occurred. Thus, the order in which the two exhibitions were held isn&rsquo;t clearly established in the sentence.&nbsp;</p>","parenttemplatename":"OSP-771-SYN","parenttemplateid":"","templateclusterid":"bbcf0ebf-d38c-4cc7-aebf-895bd1da77f4","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959352,"updateDate":1691007959352}$SATQ$::jsonb, 1691007959352, 1691007959352),
    ($SATQ$f2f6009b$SATQ$, $SATQ$e9f6a4dd-516c-4460-a847-a065224c7b93$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Little is known about the life of Wong Fei-hung (1847&ndash;1925).</li>
<li>He was born near Foshan, China, and gained local recognition as a physician and Hung Ga (also known as Hung Gar) Kung Fu master.</li>
<li>He achieved many incredible martial arts feats&mdash;some confirmed and some rumored.</li>
<li>He has become an internationally known folk hero thanks to his depiction in over a hundred films, television shows, and other media.</li>
<li>In the 1991 film <em>Once Upon a Time in China</em>, actor Jet Li portrays Wong Fei-hung using superhuman kung fu abilities to save his community.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize the effect media had on building Wong Fei-hung&rsquo;s legacy. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"91804abd-604e-456f-8fa4-85b01045439e","content":"<p>Thanks to his depiction in over a hundred pieces of media, Wong Fei-hung was locally known as a successful physician and Hung Ga Kung Fu master.</p>"},{"id":"599e05f4-5d06-4354-95e7-bbebc151ece7","content":"<p>Though he was known locally during his lifetime, Wong Fei-hung&rsquo;s later depiction in television, film, and other media has turned him into an internationally known folk hero.</p>"},{"id":"a0899bdf-5023-4848-83b0-e8e0d775baa7","content":"<p>Various media have depicted Wong Fei-hung, the successful physician and kung fu master who became an internationally known folk hero.</p>"},{"id":"42ec81b5-9bb7-4c19-89e4-69957a0993cf","content":"<p>Wong Fei-hung&rsquo;s abilities as a kung fu master are depicted in many media, including the 1991 film <em>Once Upon a Time in China</em>.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["599e05f4-5d06-4354-95e7-bbebc151ece7"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The sentence emphasizes the effect media had on building Wong Fei-hung&rsquo;s legacy, noting that media depictions after his lifetime turned Wong Fei-hung into an internationally known folk hero.</p><p>Choice A is incorrect. While it appears to emphasize the effect of media depictions of Wong Fei-hung, the sentence misrepresents information from the notes. According to the notes, media depictions resulted in Wong Fei-hung becoming an internationally known folk hero, not a locally known physician and kung fu master. Choice C is incorrect. The sentence discusses Wong Fei-hung&rsquo;s legacy, noting that he became an internationally known folk hero, but it doesn&rsquo;t emphasize the effect media had on building that legacy. Choice D is incorrect. The sentence indicates that Wong Fei-hung has been depicted in many media but doesn&rsquo;t emphasize the effect of these media depictions on building his legacy.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f2f6009b","external_id":"e9f6a4dd-516c-4460-a847-a065224c7b93","vaultid":null,"uId":"c243cae6-e5f9-4873-a5b9-75f11757e89a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Little is known about the life of Wong Fei-hung (1847&ndash;1925).</li>\n<li>He was born near Foshan, China, and gained local recognition as a physician and Hung Ga (also known as Hung Gar) Kung Fu master.</li>\n<li>He achieved many incredible martial arts feats&mdash;some confirmed and some rumored.</li>\n<li>He has become an internationally known folk hero thanks to his depiction in over a hundred films, television shows, and other media.</li>\n<li>In the 1991 film <em>Once Upon a Time in China</em>, actor Jet Li portrays Wong Fei-hung using superhuman kung fu abilities to save his community.</li>\n</ul>","stem":"<p>The student wants to emphasize the effect media had on building Wong Fei-hung&rsquo;s legacy. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"91804abd-604e-456f-8fa4-85b01045439e","content":"<p>Thanks to his depiction in over a hundred pieces of media, Wong Fei-hung was locally known as a successful physician and Hung Ga Kung Fu master.</p>"},{"id":"599e05f4-5d06-4354-95e7-bbebc151ece7","content":"<p>Though he was known locally during his lifetime, Wong Fei-hung&rsquo;s later depiction in television, film, and other media has turned him into an internationally known folk hero.</p>"},{"id":"a0899bdf-5023-4848-83b0-e8e0d775baa7","content":"<p>Various media have depicted Wong Fei-hung, the successful physician and kung fu master who became an internationally known folk hero.</p>"},{"id":"42ec81b5-9bb7-4c19-89e4-69957a0993cf","content":"<p>Wong Fei-hung&rsquo;s abilities as a kung fu master are depicted in many media, including the 1991 film <em>Once Upon a Time in China</em>.</p>"}],"keys":["599e05f4-5d06-4354-95e7-bbebc151ece7"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The sentence emphasizes the effect media had on building Wong Fei-hung&rsquo;s legacy, noting that media depictions after his lifetime turned Wong Fei-hung into an internationally known folk hero.</p><p>Choice A is incorrect. While it appears to emphasize the effect of media depictions of Wong Fei-hung, the sentence misrepresents information from the notes. According to the notes, media depictions resulted in Wong Fei-hung becoming an internationally known folk hero, not a locally known physician and kung fu master. Choice C is incorrect. The sentence discusses Wong Fei-hung&rsquo;s legacy, noting that he became an internationally known folk hero, but it doesn&rsquo;t emphasize the effect media had on building that legacy. Choice D is incorrect. The sentence indicates that Wong Fei-hung has been depicted in many media but doesn&rsquo;t emphasize the effect of these media depictions on building his legacy.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669214,"updateDate":1743430669214}$SATQ$::jsonb, 1743430669214, 1743430669214),
    ($SATQ$f33f0892$SATQ$, $SATQ$733266a8-a471-4787-a677-3e08b58e96c3$SATQ$::uuid, $SATQ$8251bbd0-229f-4936-8069-30fcf8b79065$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Although novels and poems are considered distinct literary forms, many authors have created hybrid works that incorporate elements of both. Bernardine Evaristo&rsquo;s <em>The Emperor&rsquo;s Babe</em>, <span aria-hidden="true">______</span><span class="sr-only">blank</span> is a verse novel, a book-length narrative complete with characters and a plot but conveyed in short, crisp lines of poetry rather than prose.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"d45787e4-5e43-4ec1-ab37-7b7df495173a","content":"<p>by contrast,</p>"},{"id":"7753aca2-ca78-4438-99cb-ca769135321a","content":"<p>consequently,</p>"},{"id":"3fba9055-fb64-45be-82b1-27be6f3b527c","content":"<p>secondly,</p>"},{"id":"d3a3d9dc-e0c8-4a62-b288-aead7548656f","content":"<p>for example,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["d3a3d9dc-e0c8-4a62-b288-aead7548656f"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. &ldquo;For example&rdquo; logically signals that the information in this sentence&mdash;that <em>The Emperor&rsquo;s Babe</em> is a novel conveyed in lines of poetry&mdash;exemplifies the claim in the previous sentence about hybrid works that incorporate elements of both novels and poems. </p><p>Choice A is incorrect because &ldquo;by contrast&rdquo; illogically signals that the information in this sentence contrasts with the claim about hybrid works in the previous sentence. Instead, the information demonstrates that Evaristo&rsquo;s novel is an example of a hybrid work.&nbsp;Choice B is incorrect because &ldquo;consequently&rdquo; illogically signals that the information in this sentence is a consequence, or result, of the claim about hybrid works in the previous sentence. Instead, the information demonstrates that Evaristo&rsquo;s novel is an example of a hybrid work. Choice C is incorrect because &ldquo;secondly&rdquo; illogically signals that the information in this sentence is a second, separate claim from the previous sentence&rsquo;s claim about hybrid works. Instead, the information demonstrates that Evaristo&rsquo;s novel is an example of a hybrid work. </p>$SATQ$, false, 0, $SATQ$OSP-204-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$4cc79f4c-7efe-41f0-802d-529935a2931a$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f33f0892","external_id":"733266a8-a471-4787-a677-3e08b58e96c3","vaultid":"8251bbd0-229f-4936-8069-30fcf8b79065","uId":"63692634-b458-491f-992b-e331eea1b488","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Although novels and poems are considered distinct literary forms, many authors have created hybrid works that incorporate elements of both. Bernardine Evaristo&rsquo;s <em>The Emperor&rsquo;s Babe</em>, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> is a verse novel, a book-length narrative complete with characters and a plot but conveyed in short, crisp lines of poetry rather than prose.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"d45787e4-5e43-4ec1-ab37-7b7df495173a","content":"<p>by contrast,</p>"},{"id":"7753aca2-ca78-4438-99cb-ca769135321a","content":"<p>consequently,</p>"},{"id":"3fba9055-fb64-45be-82b1-27be6f3b527c","content":"<p>secondly,</p>"},{"id":"d3a3d9dc-e0c8-4a62-b288-aead7548656f","content":"<p>for example,</p>"}],"keys":["d3a3d9dc-e0c8-4a62-b288-aead7548656f"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. &ldquo;For example&rdquo; logically signals that the information in this sentence&mdash;that <em>The Emperor&rsquo;s Babe</em> is a novel conveyed in lines of poetry&mdash;exemplifies the claim in the previous sentence about hybrid works that incorporate elements of both novels and poems. </p><p>Choice A is incorrect because &ldquo;by contrast&rdquo; illogically signals that the information in this sentence contrasts with the claim about hybrid works in the previous sentence. Instead, the information demonstrates that Evaristo&rsquo;s novel is an example of a hybrid work.&nbsp;Choice B is incorrect because &ldquo;consequently&rdquo; illogically signals that the information in this sentence is a consequence, or result, of the claim about hybrid works in the previous sentence. Instead, the information demonstrates that Evaristo&rsquo;s novel is an example of a hybrid work. Choice C is incorrect because &ldquo;secondly&rdquo; illogically signals that the information in this sentence is a second, separate claim from the previous sentence&rsquo;s claim about hybrid works. Instead, the information demonstrates that Evaristo&rsquo;s novel is an example of a hybrid work. </p>","parenttemplatename":"OSP-204-TRA","parenttemplateid":"","templateclusterid":"4cc79f4c-7efe-41f0-802d-529935a2931a","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959325,"updateDate":1691007959325}$SATQ$::jsonb, 1691007959325, 1691007959325),
    ($SATQ$f4b63a04$SATQ$, $SATQ$ba326bd3-4344-46af-9257-c70f53076429$SATQ$::uuid, $SATQ$56a69a9c-6eee-4ec6-ad77-48f1811cf6d0$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:&nbsp;</p>
<ul>
<li>In 2013, paleontology professor Hesham Sallam and his students from Mansoura University in Egypt made a discovery.</li>
<li>The team found a partial dinosaur skeleton at a site in Egypt&rsquo;s Dakhla Oasis.</li>
<li>The skeleton belonged to a dinosaur species that lived approximately 80 million years ago.</li>
<li>The new species was named <em>Mansourasaurus </em>to recognize&nbsp;the team that discovered it.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to explain the origin of the species&rsquo; name. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"f8b57cd9-640e-48ba-b593-e15d984b3763","content":"<p><em>Mansourasaurus, </em>a new species discovered in Egypt in 2013, lived<em> </em>approximately 80 million years ago.</p>"},{"id":"5ffeab2d-b64d-4249-8873-e9876e7b9809","content":"<p>A partial dinosaur skeleton found in Egypt&rsquo;s Dakhla Oasis belonged to a species named <em>Mansourasaurus</em>.</p>"},{"id":"0e415d10-8310-41ad-8568-cc47aefa75ed","content":"<p><em>Mansourasaurus, </em>a species that&nbsp;lived approximately 80 million years ago, was discovered in 2013 by Egyptian paleontologist Hesham Sallam and a team of university students.</p>"},{"id":"431aa404-5f10-4ccf-8ce9-d22256abb0f1","content":"<p>The new species was named <em>Mansourasaurus</em> to recognize the team that discovered it, a professor and students from Mansoura University.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["431aa404-5f10-4ccf-8ce9-d22256abb0f1"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. It explains where the dinosaur&rsquo;s name came from. </p><p>Choice A is incorrect. This choice does not explain the origin of the dinosaur&rsquo;s name. Choice B is incorrect. This choice does not explain the origin of the dinosaur&rsquo;s name. Choice C is incorrect. This choice does not explain the origin of the dinosaur&rsquo;s name. </p>$SATQ$, false, 0, $SATQ$OSP-KA-SYN-E003$SATQ$, $SATQ$$SATQ$, $SATQ$6b62be55-b084-4018-85a2-463944e769dc$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f4b63a04","external_id":"ba326bd3-4344-46af-9257-c70f53076429","vaultid":"56a69a9c-6eee-4ec6-ad77-48f1811cf6d0","uId":"56b0d513-462a-4a80-90f7-1b1aaad7739e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:&nbsp;</p>\n<ul>\n<li>In 2013, paleontology professor Hesham Sallam and his students from Mansoura University in Egypt made a discovery.</li>\n<li>The team found a partial dinosaur skeleton at a site in Egypt&rsquo;s Dakhla Oasis.</li>\n<li>The skeleton belonged to a dinosaur species that lived approximately 80 million years ago.</li>\n<li>The new species was named <em>Mansourasaurus </em>to recognize&nbsp;the team that discovered it.</li>\n</ul>","stem":"<p>The student wants to explain the origin of the species&rsquo; name. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"f8b57cd9-640e-48ba-b593-e15d984b3763","content":"<p><em>Mansourasaurus, </em>a new species discovered in Egypt in 2013, lived<em> </em>approximately 80 million years ago.</p>"},{"id":"5ffeab2d-b64d-4249-8873-e9876e7b9809","content":"<p>A partial dinosaur skeleton found in Egypt&rsquo;s Dakhla Oasis belonged to a species named <em>Mansourasaurus</em>.</p>"},{"id":"0e415d10-8310-41ad-8568-cc47aefa75ed","content":"<p><em>Mansourasaurus, </em>a species that&nbsp;lived approximately 80 million years ago, was discovered in 2013 by Egyptian paleontologist Hesham Sallam and a team of university students.</p>"},{"id":"431aa404-5f10-4ccf-8ce9-d22256abb0f1","content":"<p>The new species was named <em>Mansourasaurus</em> to recognize the team that discovered it, a professor and students from Mansoura University.</p>"}],"keys":["431aa404-5f10-4ccf-8ce9-d22256abb0f1"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. It explains where the dinosaur&rsquo;s name came from. </p><p>Choice A is incorrect. This choice does not explain the origin of the dinosaur&rsquo;s name. Choice B is incorrect. This choice does not explain the origin of the dinosaur&rsquo;s name. Choice C is incorrect. This choice does not explain the origin of the dinosaur&rsquo;s name. </p>","parenttemplatename":"OSP-KA-SYN-E003","parenttemplateid":"","templateclusterid":"6b62be55-b084-4018-85a2-463944e769dc","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959371,"updateDate":1691007959371}$SATQ$::jsonb, 1691007959371, 1691007959371),
    ($SATQ$f5149550$SATQ$, $SATQ$544458e0-8ddf-44f9-afc2-94b9af641d31$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>A staunch supporter of women&rsquo;s voting rights, Wilhelmina Kekelaokalaninui Widemann Dowsett sought to coordinate the efforts of suffragists in her native Hawai&lsquo;i. <span aria-hidden="true">______</span><span class="sr-only">blank</span> in 1912, she founded the National Women&rsquo;s Equal Suffrage Association of Hawai&lsquo;i, an organization that lobbied for women&rsquo;s voting rights in the US territory.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"aeab1f30-2a7a-4d1f-8bd7-02a1d084ecf3","content":"<p>In other words,</p>"},{"id":"535b5ceb-6bd8-4f25-8c4a-77f8d3009585","content":"<p>Conversely,</p>"},{"id":"3b86f7cb-b583-47f2-8f21-e6df00ebb67a","content":"<p>To that end,&nbsp;</p>"},{"id":"898d5f24-11e8-4473-9501-ce94fab9457f","content":"<p>Alternatively,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["3b86f7cb-b583-47f2-8f21-e6df00ebb67a"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. &ldquo;To that end&rdquo; logically signals that the information in this sentence&mdash;that Dowsett founded the National Women&rsquo;s Equal Suffrage Association of Hawai&lsquo;i&mdash;describes an action Dowsett took to achieve the goal stated in the previous sentence: to coordinate the efforts of suffragists in Hawai&lsquo;i.</p><p>Choice A is incorrect because &ldquo;in other words&rdquo; illogically signals that the information in this sentence about Dowsett founding a women&rsquo;s suffrage association is a paraphrase or restatement of the previous information about Dowsett seeking to coordinate suffragists&rsquo; efforts. Instead, the sentence describes a specific action Dowsett took to achieve this goal. Choice B is incorrect because &ldquo;conversely&rdquo; illogically signals that the information in this sentence about Dowsett founding a women&rsquo;s suffrage association contrasts with the previous information about Dowsett seeking to coordinate suffragists&rsquo; efforts. Instead, the sentence describes a specific action Dowsett took to achieve this goal. Choice D is incorrect because &ldquo;alternatively&rdquo; illogically signals that the information in this sentence about Dowsett founding a women&rsquo;s suffrage association presents an alternative to her seeking to coordinate suffragists&rsquo; efforts. Instead, the sentence describes a specific action Dowsett took to achieve this goal.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f5149550","external_id":"544458e0-8ddf-44f9-afc2-94b9af641d31","vaultid":null,"uId":"4fe45325-e655-4372-b3ff-957f256a7301","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>A staunch supporter of women&rsquo;s voting rights, Wilhelmina Kekelaokalaninui Widemann Dowsett sought to coordinate the efforts of suffragists in her native Hawai&lsquo;i. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> in 1912, she founded the National Women&rsquo;s Equal Suffrage Association of Hawai&lsquo;i, an organization that lobbied for women&rsquo;s voting rights in the US territory.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"aeab1f30-2a7a-4d1f-8bd7-02a1d084ecf3","content":"<p>In other words,</p>"},{"id":"535b5ceb-6bd8-4f25-8c4a-77f8d3009585","content":"<p>Conversely,</p>"},{"id":"3b86f7cb-b583-47f2-8f21-e6df00ebb67a","content":"<p>To that end,&nbsp;</p>"},{"id":"898d5f24-11e8-4473-9501-ce94fab9457f","content":"<p>Alternatively,</p>"}],"keys":["3b86f7cb-b583-47f2-8f21-e6df00ebb67a"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. &ldquo;To that end&rdquo; logically signals that the information in this sentence&mdash;that Dowsett founded the National Women&rsquo;s Equal Suffrage Association of Hawai&lsquo;i&mdash;describes an action Dowsett took to achieve the goal stated in the previous sentence: to coordinate the efforts of suffragists in Hawai&lsquo;i.</p><p>Choice A is incorrect because &ldquo;in other words&rdquo; illogically signals that the information in this sentence about Dowsett founding a women&rsquo;s suffrage association is a paraphrase or restatement of the previous information about Dowsett seeking to coordinate suffragists&rsquo; efforts. Instead, the sentence describes a specific action Dowsett took to achieve this goal. Choice B is incorrect because &ldquo;conversely&rdquo; illogically signals that the information in this sentence about Dowsett founding a women&rsquo;s suffrage association contrasts with the previous information about Dowsett seeking to coordinate suffragists&rsquo; efforts. Instead, the sentence describes a specific action Dowsett took to achieve this goal. Choice D is incorrect because &ldquo;alternatively&rdquo; illogically signals that the information in this sentence about Dowsett founding a women&rsquo;s suffrage association presents an alternative to her seeking to coordinate suffragists&rsquo; efforts. Instead, the sentence describes a specific action Dowsett took to achieve this goal.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771168,"updateDate":1776362771168}$SATQ$::jsonb, 1776362771168, 1776362771168),
    ($SATQ$f5959727$SATQ$, $SATQ$950fb78f-3d1d-481f-8939-613de6443c4c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Modernista architects championed nature in their designs. <span aria-hidden="true">______</span><span class="sr-only">blank</span> the wavy staircase and ornate floral tilework of Hospital de Sant Pau, a Modernista hospital designed by Llu&iacute;s Dom&egrave;nech i Montaner, couldn&rsquo;t exactly grow in a forest. Still, one sees natural influences in Dom&egrave;nech i Montaner&rsquo;s penchant for curves (rather than right angles) and plant- and animal-inspired flourishes.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"1f9bc054-8f5a-4012-a43c-385b7fe90775","content":"<p>Furthermore,</p>"},{"id":"8ec93498-1def-470f-bb47-0d2469b473d1","content":"<p>Similarly,</p>"},{"id":"7c45aabc-c06c-44d0-9c72-e538200ab618","content":"<p>Of course,</p>"},{"id":"634ebb7d-d345-4c25-821e-e621e4d5fb14","content":"<p>Thus,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["7c45aabc-c06c-44d0-9c72-e538200ab618"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. "Of course" logically signals that the information in this sentence&mdash;that "the wavy staircase and ornate floral tilework" of the Modernista hospital couldn&rsquo;t actually grow in a forest&mdash;acknowledges an obvious limitation of, or qualification to, the previous claim that Modernista architects championed nature in their designs.</p><p>Choice A is incorrect because "furthermore" illogically signals that the information in this sentence merely adds to the previous claim that Modernista architects championed nature in their designs. Instead, the sentence acknowledges an obvious limitation in how literally that natural influence was expressed in the hospital&rsquo;s features. Choice B is incorrect because "similarly" illogically signals that the information in this sentence is similar to the previous claim that Modernista architects championed nature in their designs. Instead, the sentence acknowledges an obvious limitation in how literally that natural influence was expressed in the hospital&rsquo;s features. Choice D is incorrect because "thus" illogically signals that the information in this sentence is a result of the previous claim that Modernista architects championed nature in their designs. Instead, the sentence acknowledges an obvious limitation in how literally that natural influence was expressed in the hospital&rsquo;s features.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f5959727","external_id":"950fb78f-3d1d-481f-8939-613de6443c4c","vaultid":null,"uId":"46e4b0de-57a4-43ea-8ada-1695936ac5ec","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Modernista architects championed nature in their designs. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the wavy staircase and ornate floral tilework of Hospital de Sant Pau, a Modernista hospital designed by Llu&iacute;s Dom&egrave;nech i Montaner, couldn&rsquo;t exactly grow in a forest. Still, one sees natural influences in Dom&egrave;nech i Montaner&rsquo;s penchant for curves (rather than right angles) and plant- and animal-inspired flourishes.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"1f9bc054-8f5a-4012-a43c-385b7fe90775","content":"<p>Furthermore,</p>"},{"id":"8ec93498-1def-470f-bb47-0d2469b473d1","content":"<p>Similarly,</p>"},{"id":"7c45aabc-c06c-44d0-9c72-e538200ab618","content":"<p>Of course,</p>"},{"id":"634ebb7d-d345-4c25-821e-e621e4d5fb14","content":"<p>Thus,</p>"}],"keys":["7c45aabc-c06c-44d0-9c72-e538200ab618"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. \"Of course\" logically signals that the information in this sentence&mdash;that \"the wavy staircase and ornate floral tilework\" of the Modernista hospital couldn&rsquo;t actually grow in a forest&mdash;acknowledges an obvious limitation of, or qualification to, the previous claim that Modernista architects championed nature in their designs.</p><p>Choice A is incorrect because \"furthermore\" illogically signals that the information in this sentence merely adds to the previous claim that Modernista architects championed nature in their designs. Instead, the sentence acknowledges an obvious limitation in how literally that natural influence was expressed in the hospital&rsquo;s features. Choice B is incorrect because \"similarly\" illogically signals that the information in this sentence is similar to the previous claim that Modernista architects championed nature in their designs. Instead, the sentence acknowledges an obvious limitation in how literally that natural influence was expressed in the hospital&rsquo;s features. Choice D is incorrect because \"thus\" illogically signals that the information in this sentence is a result of the previous claim that Modernista architects championed nature in their designs. Instead, the sentence acknowledges an obvious limitation in how literally that natural influence was expressed in the hospital&rsquo;s features.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061190,"updateDate":1755117061190}$SATQ$::jsonb, 1755117061190, 1755117061190),
    ($SATQ$f5a00eff$SATQ$, $SATQ$3cb17aea-6417-4349-92c8-01f629ddd643$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>If the formation of Earth&rsquo;s mantle had been purely a product of core differentiation&mdash;whereby heavier elements sink toward the core and lighter elements rise&mdash;the upper mantle would be depleted of heavy siderophile elements. Siderophiles are much more abundant in the mantle than predicted in that model, however. <span aria-hidden="true">______</span><span class="sr-only">blank</span> extraterrestrial material containing siderophiles, likely from asteroid or comet impacts, almost certainly accreted to Earth following core differentiation.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"f91e5947-188c-4739-862f-c1416907ad78","content":"<p>That said,</p>"},{"id":"a967661c-dcc7-44d6-8672-8f6fda508f43","content":"<p>Hence,</p>"},{"id":"40af1a35-62fc-476c-8745-0b03c16cd191","content":"<p>For example, &nbsp;</p>"},{"id":"b088b997-6af4-43fc-8e79-2e5db176d250","content":"<p>Likewise,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["a967661c-dcc7-44d6-8672-8f6fda508f43"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. "Hence" correctly signals that the claim in this sentence regarding extraterrestrial material follows logically from the information in the previous sentences. The previous sentences establish that siderophile elements in the mantle are more abundant than predicted in the core-differentiation model. This sentence claims, logically, that these elements came from extraterrestrial material that accreted to Earth <em>after</em> core differentiation.</p><p>Choice A is incorrect because "that said" illogically signals that the information in this sentence regarding extraterrestrial material is an exception to the previous information about siderophiles&rsquo; abundance in the mantle. Instead, it is a new claim that follows logically from the previous information. Choice C is incorrect because "for example" illogically signals that the information in this sentence regarding extraterrestrial material exemplifies the previous information about siderophiles&rsquo; abundance in the mantle. Instead, it is a new claim that follows logically from the previous information. Choice D is incorrect because "likewise" illogically signals that the information in this sentence regarding extraterrestrial material is merely similar to the previous information about siderophiles&rsquo; abundance in the mantle. Instead, it is a new claim that follows logically from the previous information.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f5a00eff","external_id":"3cb17aea-6417-4349-92c8-01f629ddd643","vaultid":null,"uId":"dc264012-93af-49ca-9925-3d748653c8c4","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>If the formation of Earth&rsquo;s mantle had been purely a product of core differentiation&mdash;whereby heavier elements sink toward the core and lighter elements rise&mdash;the upper mantle would be depleted of heavy siderophile elements. Siderophiles are much more abundant in the mantle than predicted in that model, however. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> extraterrestrial material containing siderophiles, likely from asteroid or comet impacts, almost certainly accreted to Earth following core differentiation.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"f91e5947-188c-4739-862f-c1416907ad78","content":"<p>That said,</p>"},{"id":"a967661c-dcc7-44d6-8672-8f6fda508f43","content":"<p>Hence,</p>"},{"id":"40af1a35-62fc-476c-8745-0b03c16cd191","content":"<p>For example, &nbsp;</p>"},{"id":"b088b997-6af4-43fc-8e79-2e5db176d250","content":"<p>Likewise,</p>"}],"keys":["a967661c-dcc7-44d6-8672-8f6fda508f43"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. \"Hence\" correctly signals that the claim in this sentence regarding extraterrestrial material follows logically from the information in the previous sentences. The previous sentences establish that siderophile elements in the mantle are more abundant than predicted in the core-differentiation model. This sentence claims, logically, that these elements came from extraterrestrial material that accreted to Earth <em>after</em> core differentiation.</p><p>Choice A is incorrect because \"that said\" illogically signals that the information in this sentence regarding extraterrestrial material is an exception to the previous information about siderophiles&rsquo; abundance in the mantle. Instead, it is a new claim that follows logically from the previous information. Choice C is incorrect because \"for example\" illogically signals that the information in this sentence regarding extraterrestrial material exemplifies the previous information about siderophiles&rsquo; abundance in the mantle. Instead, it is a new claim that follows logically from the previous information. Choice D is incorrect because \"likewise\" illogically signals that the information in this sentence regarding extraterrestrial material is merely similar to the previous information about siderophiles&rsquo; abundance in the mantle. Instead, it is a new claim that follows logically from the previous information.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669205,"updateDate":1743430669205}$SATQ$::jsonb, 1743430669205, 1743430669205),
    ($SATQ$f6d454c1$SATQ$, $SATQ$c3fb024d-054c-423f-bb42-cf33987d4d10$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>If a moon orbiting a planet comes close enough to that planet, tidal forces can cause the moon to break apart.</li>
<li>In a 2022 study, researchers proposed that Saturn was once orbited by a large moon they named Chrysalis.</li>
<li>Their simulations indicated that Chrysalis would likely have come very close to Saturn around 160 million years ago.</li>
<li>At that distance, Chrysalis would have been broken apart by tidal forces.</li>
<li>The researchers hypothesized that the resulting debris formed Saturn&rsquo;s rings.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to recount the sequence of events proposed by the researchers. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"126b601e-da71-4fbc-bf32-b6805c2dde41","content":"<p>According to researchers&rsquo; simulations, two events likely occurred around 160 million years ago: first, Chrysalis came very close to Saturn, and second, debris from Saturn&rsquo;s rings caused the moon to break apart.</p>"},{"id":"f00989c6-fd4a-490e-95aa-147a906ffced","content":"<p>If a moon orbiting a planet (like Saturn) comes close enough to that planet, tidal forces can cause the moon to break apart.</p>"},{"id":"696bdbbf-7c8b-4873-8d45-34ad7b278b11","content":"<p>Around 160 million years ago, a large moon (Chrysalis) came close enough to Saturn that tidal forces broke the moon apart; its debris then formed the planet&rsquo;s rings.&nbsp;</p>"},{"id":"6f5aa168-ab6f-43a7-a581-0a871f04782c","content":"<p>First, researchers proposed that Saturn was orbited by a large moon (Chrysalis); next, they conducted simulations; and, finally, they formed a hypothesis.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["696bdbbf-7c8b-4873-8d45-34ad7b278b11"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence recounts the sequence of events proposed by the researchers: a large moon orbiting Saturn came close enough to the planet that it was broken apart by tidal forces, and the resulting debris formed Saturn&rsquo;s rings.</p><p>Choice A is incorrect because the sentence misrepresents information from the notes; according to the notes, tidal forces, not debris, caused the moon to break apart. Choice B is incorrect. The sentence offers information relevant to the 2022 study but doesn&rsquo;t recount the sequence of events proposed by the researchers. Choice D is incorrect. The sentence recounts a sequence, but it&rsquo;s a sequence of the researchers&rsquo; activities, not the sequence of events proposed by the researchers.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f6d454c1","external_id":"c3fb024d-054c-423f-bb42-cf33987d4d10","vaultid":null,"uId":"fbbd4fef-3672-4910-87ed-f640c0e7f1a2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>If a moon orbiting a planet comes close enough to that planet, tidal forces can cause the moon to break apart.</li>\n<li>In a 2022 study, researchers proposed that Saturn was once orbited by a large moon they named Chrysalis.</li>\n<li>Their simulations indicated that Chrysalis would likely have come very close to Saturn around 160 million years ago.</li>\n<li>At that distance, Chrysalis would have been broken apart by tidal forces.</li>\n<li>The researchers hypothesized that the resulting debris formed Saturn&rsquo;s rings.</li>\n</ul>","stem":"<p>The student wants to recount the sequence of events proposed by the researchers. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"126b601e-da71-4fbc-bf32-b6805c2dde41","content":"<p>According to researchers&rsquo; simulations, two events likely occurred around 160 million years ago: first, Chrysalis came very close to Saturn, and second, debris from Saturn&rsquo;s rings caused the moon to break apart.</p>"},{"id":"f00989c6-fd4a-490e-95aa-147a906ffced","content":"<p>If a moon orbiting a planet (like Saturn) comes close enough to that planet, tidal forces can cause the moon to break apart.</p>"},{"id":"696bdbbf-7c8b-4873-8d45-34ad7b278b11","content":"<p>Around 160 million years ago, a large moon (Chrysalis) came close enough to Saturn that tidal forces broke the moon apart; its debris then formed the planet&rsquo;s rings.&nbsp;</p>"},{"id":"6f5aa168-ab6f-43a7-a581-0a871f04782c","content":"<p>First, researchers proposed that Saturn was orbited by a large moon (Chrysalis); next, they conducted simulations; and, finally, they formed a hypothesis.</p>"}],"keys":["696bdbbf-7c8b-4873-8d45-34ad7b278b11"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence recounts the sequence of events proposed by the researchers: a large moon orbiting Saturn came close enough to the planet that it was broken apart by tidal forces, and the resulting debris formed Saturn&rsquo;s rings.</p><p>Choice A is incorrect because the sentence misrepresents information from the notes; according to the notes, tidal forces, not debris, caused the moon to break apart. Choice B is incorrect. The sentence offers information relevant to the 2022 study but doesn&rsquo;t recount the sequence of events proposed by the researchers. Choice D is incorrect. The sentence recounts a sequence, but it&rsquo;s a sequence of the researchers&rsquo; activities, not the sequence of events proposed by the researchers.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669213,"updateDate":1743430669213}$SATQ$::jsonb, 1743430669213, 1743430669213),
    ($SATQ$f735493e$SATQ$, $SATQ$c6ba56a9-8d3b-489d-b21a-df9f68e41920$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Celebrated Tewa potter Maria Martinez (1887&ndash;1980) made her signature all-black ceramic vessels using a heating technique called reduction firing. This technique involves smothering the flame surrounding the clay vessel. <span aria-hidden="true">______</span><span class="sr-only">blank</span> the vessel takes on a shiny, black hue. &nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"75bc3e92-9508-4eb0-b56b-35b022da1a7e","content":"<p>On the contrary,</p>"},{"id":"0279df48-d124-4988-b0ae-61ce95e3446b","content":"<p>For example,</p>"},{"id":"75b9acd4-2ac4-4cac-96d5-b5d8093844c6","content":"<p>Previously,</p>"},{"id":"58846327-bb37-4422-bd03-6e8f2c724fd1","content":"<p>As a result, &nbsp;&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["58846327-bb37-4422-bd03-6e8f2c724fd1"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. "As a result" logically signals that the information in this sentence&mdash;the vessel turning black&mdash;is a result of the heating technique discussed in the previous sentence.</p><p>Choice A is incorrect because "on the contrary" illogically signals that the information in this sentence directly opposes the heating technique in the previous sentence. Instead, the vessel turns black as a result of that technique. Choice B is incorrect because "for example" illogically signals that the information in this sentence is an example of the heating technique in the previous sentence. Instead, the vessel turns black as a result of that technique. Choice C is incorrect because "previously" illogically signals that the information in this sentence occurs earlier in a chronological series of events than does the heating technique discussed in the first two sentences. Instead, the vessel turns black as a result of that technique.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f735493e","external_id":"c6ba56a9-8d3b-489d-b21a-df9f68e41920","vaultid":null,"uId":"2874931c-bbdf-4916-abea-1194c0cd6e23","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Celebrated Tewa potter Maria Martinez (1887&ndash;1980) made her signature all-black ceramic vessels using a heating technique called reduction firing. This technique involves smothering the flame surrounding the clay vessel. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the vessel takes on a shiny, black hue. &nbsp;</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"75bc3e92-9508-4eb0-b56b-35b022da1a7e","content":"<p>On the contrary,</p>"},{"id":"0279df48-d124-4988-b0ae-61ce95e3446b","content":"<p>For example,</p>"},{"id":"75b9acd4-2ac4-4cac-96d5-b5d8093844c6","content":"<p>Previously,</p>"},{"id":"58846327-bb37-4422-bd03-6e8f2c724fd1","content":"<p>As a result, &nbsp;&nbsp;</p>"}],"keys":["58846327-bb37-4422-bd03-6e8f2c724fd1"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. \"As a result\" logically signals that the information in this sentence&mdash;the vessel turning black&mdash;is a result of the heating technique discussed in the previous sentence.</p><p>Choice A is incorrect because \"on the contrary\" illogically signals that the information in this sentence directly opposes the heating technique in the previous sentence. Instead, the vessel turns black as a result of that technique. Choice B is incorrect because \"for example\" illogically signals that the information in this sentence is an example of the heating technique in the previous sentence. Instead, the vessel turns black as a result of that technique. Choice C is incorrect because \"previously\" illogically signals that the information in this sentence occurs earlier in a chronological series of events than does the heating technique discussed in the first two sentences. Instead, the vessel turns black as a result of that technique.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323043,"updateDate":1730147323043}$SATQ$::jsonb, 1730147323043, 1730147323043),
    ($SATQ$f8c4591b$SATQ$, $SATQ$4be7caa8-e069-4346-af6c-a5ba998eeef5$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>With their distinctive cone shapes and steeply sloping sides, the volcanoes Hverfjall (Iceland) and Toliman (Guatemala) may look similar from afar. Tehnuka Ilanko and other volcanologists, <span aria-hidden="true">______</span><span class="sr-only">blank</span> can tell by how each was formed that Hverfjall is a cinder cone volcano, while Toliman is a composite volcano.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"03d41127-b25f-4baa-8bf8-6e59f86612c7","content":"<p>for example,</p>"},{"id":"70f056fd-ab67-47af-b432-0e261c65f16a","content":"<p>in addition,</p>"},{"id":"6f8304c4-f18f-45d6-aa17-63123d07939e","content":"<p>therefore,</p>"},{"id":"fd35aa71-88a0-4ab9-a5ca-391911582c1d","content":"<p>though,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["fd35aa71-88a0-4ab9-a5ca-391911582c1d"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. "Though" logically signals that the information in this sentence&mdash;that volcanologists can distinguish the two volcanoes by how they were formed&mdash;presents a qualification or exception to the previous statement that the volcanoes look similar. The volcanoes are actually of two different types.</p><p>Choice A is incorrect because "for example" illogically signals that the information in this sentence exemplifies the previous information about the volcanoes looking similar. Instead, the sentence presents a qualification to that apparent similarity&mdash;the volcanoes are actually of two different types. Choice B is incorrect because "in addition" illogically signals that the information in this sentence merely adds to the previous information about the volcanoes looking similar. Instead, the sentence presents a qualification to that apparent similarity&mdash;the volcanoes are actually of two different types. Choice C is incorrect because "therefore" illogically signals that the information in this sentence is a result of the previous information about the volcanoes looking similar. Instead, the sentence presents a qualification to that apparent similarity&mdash;the volcanoes are actually of two different types.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f8c4591b","external_id":"4be7caa8-e069-4346-af6c-a5ba998eeef5","vaultid":null,"uId":"61a8f1f7-81a4-4960-814c-88453ecc804e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>With their distinctive cone shapes and steeply sloping sides, the volcanoes Hverfjall (Iceland) and Toliman (Guatemala) may look similar from afar. Tehnuka Ilanko and other volcanologists, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> can tell by how each was formed that Hverfjall is a cinder cone volcano, while Toliman is a composite volcano.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"03d41127-b25f-4baa-8bf8-6e59f86612c7","content":"<p>for example,</p>"},{"id":"70f056fd-ab67-47af-b432-0e261c65f16a","content":"<p>in addition,</p>"},{"id":"6f8304c4-f18f-45d6-aa17-63123d07939e","content":"<p>therefore,</p>"},{"id":"fd35aa71-88a0-4ab9-a5ca-391911582c1d","content":"<p>though,</p>"}],"keys":["fd35aa71-88a0-4ab9-a5ca-391911582c1d"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. \"Though\" logically signals that the information in this sentence&mdash;that volcanologists can distinguish the two volcanoes by how they were formed&mdash;presents a qualification or exception to the previous statement that the volcanoes look similar. The volcanoes are actually of two different types.</p><p>Choice A is incorrect because \"for example\" illogically signals that the information in this sentence exemplifies the previous information about the volcanoes looking similar. Instead, the sentence presents a qualification to that apparent similarity&mdash;the volcanoes are actually of two different types. Choice B is incorrect because \"in addition\" illogically signals that the information in this sentence merely adds to the previous information about the volcanoes looking similar. Instead, the sentence presents a qualification to that apparent similarity&mdash;the volcanoes are actually of two different types. Choice C is incorrect because \"therefore\" illogically signals that the information in this sentence is a result of the previous information about the volcanoes looking similar. Instead, the sentence presents a qualification to that apparent similarity&mdash;the volcanoes are actually of two different types.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061177,"updateDate":1755117061177}$SATQ$::jsonb, 1755117061177, 1755117061177),
    ($SATQ$fb3abe38$SATQ$, $SATQ$44184b07-d595-4b34-bf13-95e1d824be36$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p><p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>In a 2020 study, researchers in California investigated how many potential nesting sites female wood ducks visited during the nesting season.</li>
<li>The researchers placed nest boxes throughout the survey area and tagged 138 female wood ducks with radio frequency ID trackers.</li>
<li>These trackers recorded how many nest boxes each duck visited.</li>
<li>67 ducks (48.5%) visited only one nest box.</li>
<li>18 ducks (13.0%) visited 10 or more nest boxes.</li>
<li>Younger ducks were more likely to visit multiple nest boxes.</li>
</ul></p>$SATQ$, $SATQ$<p>The student wants to present the methods used in the 2020 study. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"86ae5840-7598-4912-9128-dadda8246c07","content":"<p>By recording how many nest boxes each duck visited, the researchers discovered that only a relatively small percentage (13.0%) of the ducks visited 10 or more nest boxes.</p>"},{"id":"4121a2a8-bc98-49ce-8b88-aa252c4c4f9a","content":"<p>After tracking how many nest boxes the 138 wood ducks visited, the researchers found that the younger ducks tended to visit more nest boxes than the older ducks.</p>"},{"id":"81473214-3d8f-474f-a9a5-ffa9a2874008","content":"<p>The researchers tagged 138 female wood ducks with radio frequency ID trackers and recorded how many nest boxes each duck visited during the nesting season.</p>"},{"id":"5eadda8e-3172-423d-985f-d0e069d8fcad","content":"<p>The researchers investigated each nesting site for signs that it had been visited by the female wood ducks.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["81473214-3d8f-474f-a9a5-ffa9a2874008"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence presents the methods used in the study, noting that researchers tagged 138 female wood ducks with radio frequency ID trackers and recorded the number of nest boxes each duck visited.</p><p>Choice A is incorrect. While the sentence mentions an aspect of the study&rsquo;s design (that the researchers recorded the number of nest boxes the wood ducks visited), it primarily focuses on a finding of the study rather than the methods the researchers used. Choice B is incorrect. While the sentence mentions an aspect of the study&rsquo;s design (that the researchers tracked the number of nest boxes the wood ducks visited), it primarily focuses on a finding of the study rather than the methods the researchers used. Choice D is incorrect. The sentence misrepresents information from the notes. The researchers used radio frequency ID trackers to record the ducks&rsquo; visits; they didn&rsquo;t investigate each site to look for evidence that it had been visited.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"fb3abe38","external_id":"44184b07-d595-4b34-bf13-95e1d824be36","vaultid":null,"uId":"eea198d7-b1d3-4cd0-bb8b-b90e3506b95b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p><p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>In a 2020 study, researchers in California investigated how many potential nesting sites female wood ducks visited during the nesting season.</li>\n<li>The researchers placed nest boxes throughout the survey area and tagged 138 female wood ducks with radio frequency ID trackers.</li>\n<li>These trackers recorded how many nest boxes each duck visited.</li>\n<li>67 ducks (48.5%) visited only one nest box.</li>\n<li>18 ducks (13.0%) visited 10 or more nest boxes.</li>\n<li>Younger ducks were more likely to visit multiple nest boxes.</li>\n</ul></p>","stem":"<p>The student wants to present the methods used in the 2020 study. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"86ae5840-7598-4912-9128-dadda8246c07","content":"<p>By recording how many nest boxes each duck visited, the researchers discovered that only a relatively small percentage (13.0%) of the ducks visited 10 or more nest boxes.</p>"},{"id":"4121a2a8-bc98-49ce-8b88-aa252c4c4f9a","content":"<p>After tracking how many nest boxes the 138 wood ducks visited, the researchers found that the younger ducks tended to visit more nest boxes than the older ducks.</p>"},{"id":"81473214-3d8f-474f-a9a5-ffa9a2874008","content":"<p>The researchers tagged 138 female wood ducks with radio frequency ID trackers and recorded how many nest boxes each duck visited during the nesting season.</p>"},{"id":"5eadda8e-3172-423d-985f-d0e069d8fcad","content":"<p>The researchers investigated each nesting site for signs that it had been visited by the female wood ducks.</p>"}],"keys":["81473214-3d8f-474f-a9a5-ffa9a2874008"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence presents the methods used in the study, noting that researchers tagged 138 female wood ducks with radio frequency ID trackers and recorded the number of nest boxes each duck visited.</p><p>Choice A is incorrect. While the sentence mentions an aspect of the study&rsquo;s design (that the researchers recorded the number of nest boxes the wood ducks visited), it primarily focuses on a finding of the study rather than the methods the researchers used. Choice B is incorrect. While the sentence mentions an aspect of the study&rsquo;s design (that the researchers tracked the number of nest boxes the wood ducks visited), it primarily focuses on a finding of the study rather than the methods the researchers used. Choice D is incorrect. The sentence misrepresents information from the notes. The researchers used radio frequency ID trackers to record the ducks&rsquo; visits; they didn&rsquo;t investigate each site to look for evidence that it had been visited.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771168,"updateDate":1776362771168}$SATQ$::jsonb, 1776362771168, 1776362771168),
    ($SATQ$fbffb352$SATQ$, $SATQ$977bf489-037c-4bce-bcb0-1dc735c870e4$SATQ$::uuid, $SATQ$90173fd8-d6bd-4667-99cb-a7620f128bb0$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Archaeologist Dr. Sada Mire founded the Horn Heritage Foundation to preserve the cultural history of regions in the Horn of Africa.</li>
<li>Horn Heritage has overseen a preservation project to create 3D digital scans of ancient rock art in Somaliland.</li>
<li>Paintings found at the Laas Geel caves are included in the scans.</li>
<li>The Laas Geel paintings feature human figures and animals.</li>
<li>Paintings found at the Dhagah Nabi Galay caves are included in the scans.</li>
<li>The Dhagah Nabi Galay caves feature what are thought to be the earliest examples of writing in East Africa.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize a similarity between the Laas Geel paintings and the Dhagah Nabi Galay paintings. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"a5a59b76-e3e3-4c4b-897a-2bf8ac0a9c06","content":"<p>The earliest examples of writing in East Africa are thought to be featured in the paintings at the Dhagah Nabi Galay caves in Somaliland.</p>"},{"id":"aa19f3ef-9348-4b6b-87d9-780edb4b0aa5","content":"<p>The paintings at the Dhagah Nabi Galay caves feature examples of writing, while those at the Laas Geel caves feature humans and animals.</p>"},{"id":"daa96af1-aad5-426c-b960-a171a0ee41a6","content":"<p>In Somaliland, the paintings in the Laas Geel caves feature human figures and animals.</p>"},{"id":"0d2b9190-5e30-45ed-8aa2-adc6cb3df826","content":"<p>The Laas Geel paintings and the Dhagah Nabi Galay paintings are both examples of ancient rock art found in Somaliland.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["0d2b9190-5e30-45ed-8aa2-adc6cb3df826"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. This choice compares the Laas Geel paintings and the Dhagah Nabi Galay paintings to one another and emphasizes what they have in common: they are both ancient rock art found in the same region. </p><p>Choice A is incorrect. This choice only mentions the Dhagah Nabi Galay paintings. It doesn&rsquo;t compare them to the Laas Geel paintings. Choice B is incorrect. This choice doesn&rsquo;t emphasize a similarity between the two paintings. Instead, it emphasizes a difference: the type of content they depict. Choice C is incorrect. This choice only mentions the Laas Geel paintings. It doesn&rsquo;t compare them to the Dhagah Nabi Galay paintings. </p>$SATQ$, false, 0, $SATQ$OSP-KA-SYN-E007$SATQ$, $SATQ$$SATQ$, $SATQ$a70fef24-8f06-4c89-9c3a-ff73f938891e$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"fbffb352","external_id":"977bf489-037c-4bce-bcb0-1dc735c870e4","vaultid":"90173fd8-d6bd-4667-99cb-a7620f128bb0","uId":"8688d01f-910a-4561-a2f2-f91040f1f12e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Archaeologist Dr. Sada Mire founded the Horn Heritage Foundation to preserve the cultural history of regions in the Horn of Africa.</li>\n<li>Horn Heritage has overseen a preservation project to create 3D digital scans of ancient rock art in Somaliland.</li>\n<li>Paintings found at the Laas Geel caves are included in the scans.</li>\n<li>The Laas Geel paintings feature human figures and animals.</li>\n<li>Paintings found at the Dhagah Nabi Galay caves are included in the scans.</li>\n<li>The Dhagah Nabi Galay caves feature what are thought to be the earliest examples of writing in East Africa.</li>\n</ul>","stem":"<p>The student wants to emphasize a similarity between the Laas Geel paintings and the Dhagah Nabi Galay paintings. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"a5a59b76-e3e3-4c4b-897a-2bf8ac0a9c06","content":"<p>The earliest examples of writing in East Africa are thought to be featured in the paintings at the Dhagah Nabi Galay caves in Somaliland.</p>"},{"id":"aa19f3ef-9348-4b6b-87d9-780edb4b0aa5","content":"<p>The paintings at the Dhagah Nabi Galay caves feature examples of writing, while those at the Laas Geel caves feature humans and animals.</p>"},{"id":"daa96af1-aad5-426c-b960-a171a0ee41a6","content":"<p>In Somaliland, the paintings in the Laas Geel caves feature human figures and animals.</p>"},{"id":"0d2b9190-5e30-45ed-8aa2-adc6cb3df826","content":"<p>The Laas Geel paintings and the Dhagah Nabi Galay paintings are both examples of ancient rock art found in Somaliland.</p>"}],"keys":["0d2b9190-5e30-45ed-8aa2-adc6cb3df826"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. This choice compares the Laas Geel paintings and the Dhagah Nabi Galay paintings to one another and emphasizes what they have in common: they are both ancient rock art found in the same region. </p><p>Choice A is incorrect. This choice only mentions the Dhagah Nabi Galay paintings. It doesn&rsquo;t compare them to the Laas Geel paintings. Choice B is incorrect. This choice doesn&rsquo;t emphasize a similarity between the two paintings. Instead, it emphasizes a difference: the type of content they depict. Choice C is incorrect. This choice only mentions the Laas Geel paintings. It doesn&rsquo;t compare them to the Dhagah Nabi Galay paintings. </p>","parenttemplatename":"OSP-KA-SYN-E007","parenttemplateid":"","templateclusterid":"a70fef24-8f06-4c89-9c3a-ff73f938891e","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959371,"updateDate":1691007959371}$SATQ$::jsonb, 1691007959371, 1691007959371)
